interface CustomizationContextType {
  customizationState: FieldCustomizationState;
  isLoading: boolean;
  getModuleConfig: (moduleId: string) => ModuleGridConfig;
  getVisibleColumns: (moduleId: string) => GridColumnConfig[];
  isColumnVisible: (moduleId: string, columnId: string) => boolean;
  toggleColumnVisibility: (moduleId: string, columnId: string) => void;
  setColumnVisibility: (moduleId: string, columnId: string, visible: boolean) => void;
  updateColumn: (moduleId: string, columnId: string, updates: Partial<GridColumnConfig>) => void;
  reorderColumns: (moduleId: string, sourceIndex: number, destinationIndex: number) => void;
  moveColumnUp: (moduleId: string, columnId: string) => void;
  moveColumnDown: (moduleId: string, columnId: string) => void;
  setModuleDensity: (moduleId: string, density: TableDensity) => void;
  setModuleSort: (moduleId: string, sortBy: string, sortOrder: 'asc' | 'desc') => void;
  addCustomTag: (tag: string) => void;
  removeCustomTag: (tag: string) => void;
  resetModuleToDefault: (moduleId?: string) => Promise<void>;
  saveCustomizations: (stateToSave?: FieldCustomizationState) => Promise<void>;
  getDensityClasses: (density?: TableDensity) => { pyTh: string; pyTd: string; textClass: string };
}

const CustomizationContext = createContext<CustomizationContextType | undefined>(undefined);

export const CustomizationProvider: React.FC<{ children: React.ReactNode }> = ({ children }) => {
  const [customizationState, setCustomizationState] = useState<FieldCustomizationState>(() => {
    if (typeof window !== 'undefined') {
      try {
        const cached = localStorage.getItem(STORAGE_KEY);
        if (cached) {
          const parsed = JSON.parse(cached);
          return {
            ...DEFAULT_FIELD_CUSTOMIZATIONS,
            ...parsed,
            modules: {
              ...DEFAULT_FIELD_CUSTOMIZATIONS.modules,
              ...(parsed.modules || {}),
            },
          };
        }
      } catch (e) {
        console.warn('Failed to parse cached field customizations:', e);
      }
    }
    return DEFAULT_FIELD_CUSTOMIZATIONS;
  });

  const [isLoading, setIsLoading] = useState(false);

  // Sync with backend on mount
  useEffect(() => {
    let isMounted = true;
    const fetchRemote = async () => {
      try {
        setIsLoading(true);
        const remote = await SettingsService.getFieldCustomizations();
        if (remote && isMounted) {
          setCustomizationState((prev) => {
            const merged: FieldCustomizationState = {
              ...DEFAULT_FIELD_CUSTOMIZATIONS,
              ...prev,
              ...remote,
              modules: {
                ...DEFAULT_FIELD_CUSTOMIZATIONS.modules,
                ...(prev.modules || {}),
                ...(remote.modules || {}),
              },
            };
            if (typeof window !== 'undefined') {
              try {
                localStorage.setItem(STORAGE_KEY, JSON.stringify(merged));
              } catch {}
            }
            return merged;
          });
        }
      } catch (err) {
        // Backend might be offline or endpoint not yet loaded; local cache is active
        console.warn('Backend field customizations fetch deferred, using local cache');
      } finally {
        if (isMounted) setIsLoading(false);
      }
    };

    fetchRemote();
    return () => {
      isMounted = false;
    };
  }, []);

  // Save changes locally and remotely
  const persistState = useCallback(async (state: FieldCustomizationState) => {
    if (typeof window !== 'undefined') {
      try {
        localStorage.setItem(STORAGE_KEY, JSON.stringify(state));
      } catch (err) {
        console.error('Failed to write to localStorage:', err);
      }
    }

    try {
      await SettingsService.updateFieldCustomizations(state);
    } catch (err) {
      // Ignore network errors in offline/local dev
    }
  }, []);

  const saveCustomizations = useCallback(
    async (stateToSave?: FieldCustomizationState) => {
      const target = stateToSave || customizationState;
      await persistState(target);
    },
    [customizationState, persistState],
  );

  const getModuleConfig = useCallback(
    (moduleId: string): ModuleGridConfig => {
      return (
        customizationState.modules[moduleId] ||
        DEFAULT_FIELD_CUSTOMIZATIONS.modules[moduleId] || {
          moduleId,
          moduleName: moduleId,
          density: 'normal',
          columns: [],
        }
      );
    },
    [customizationState.modules],
  );

  const getVisibleColumns = useCallback(
    (moduleId: string): GridColumnConfig[] => {
      const config = getModuleConfig(moduleId);
      return [...config.columns]
        .filter((col) => col.visible)
        .sort((a, b) => (a.order ?? 0) - (b.order ?? 0));
    },
    [getModuleConfig],
  );

  const isColumnVisible = useCallback(
    (moduleId: string, columnId: string): boolean => {
      const config = getModuleConfig(moduleId);
      const col = config.columns.find((c) => c.id === columnId);
      return col ? col.visible : true;
    },
    [getModuleConfig],
  );

  const toggleColumnVisibility = useCallback(
    (moduleId: string, columnId: string) => {
      setCustomizationState((prev) => {
        const moduleCfg = prev.modules[moduleId] || DEFAULT_FIELD_CUSTOMIZATIONS.modules[moduleId];
        if (!moduleCfg) return prev;

        const updatedCols = moduleCfg.columns.map((c) => {
          if (c.id === columnId) {
            return { ...c, visible: !c.visible };
          }
          return c;
        });

        const nextState: FieldCustomizationState = {
          ...prev,
          modules: {
            ...prev.modules,
            [moduleId]: {
              ...moduleCfg,
              columns: updatedCols,
            },
          },
          updatedAt: new Date().toISOString(),
        };

        persistState(nextState);
        return nextState;
      });
    },
    [persistState],
  );

  const setColumnVisibility = useCallback(
    (moduleId: string, columnId: string, visible: boolean) => {
      setCustomizationState((prev) => {
        const moduleCfg = prev.modules[moduleId] || DEFAULT_FIELD_CUSTOMIZATIONS.modules[moduleId];
        if (!moduleCfg) return prev;

        const updatedCols = moduleCfg.columns.map((c) => {
          if (c.id === columnId) {
            return { ...c, visible };
          }
          return c;
        });

        const nextState: FieldCustomizationState = {
          ...prev,
          modules: {
            ...prev.modules,
            [moduleId]: {
              ...moduleCfg,
              columns: updatedCols,
            },
          },
          updatedAt: new Date().toISOString(),
        };

        persistState(nextState);
        return nextState;
      });
    },
    [persistState],
  );

  const updateColumn = useCallback(
    (moduleId: string, columnId: string, updates: Partial<GridColumnConfig>) => {
      setCustomizationState((prev) => {
        const moduleCfg = prev.modules[moduleId] || DEFAULT_FIELD_CUSTOMIZATIONS.modules[moduleId];
        if (!moduleCfg) return prev;

        const updatedCols = moduleCfg.columns.map((c) => {
          if (c.id === columnId) {
            return { ...c, ...updates };
          }
          return c;
        });

        const nextState: FieldCustomizationState = {
          ...prev,
          modules: {
            ...prev.modules,
            [moduleId]: {
              ...moduleCfg,
              columns: updatedCols,
            },
          },
          updatedAt: new Date().toISOString(),
        };

        persistState(nextState);
        return nextState;
      });
    },
    [persistState],
  );

  const reorderColumns = useCallback(
    (moduleId: string, sourceIndex: number, destinationIndex: number) => {
      setCustomizationState((prev) => {
        const moduleCfg = prev.modules[moduleId] || DEFAULT_FIELD_CUSTOMIZATIONS.modules[moduleId];
        if (!moduleCfg) return prev;

        const cols = [...moduleCfg.columns].sort((a, b) => (a.order ?? 0) - (b.order ?? 0));
        const [moved] = cols.splice(sourceIndex, 1);
        cols.splice(destinationIndex, 0, moved);

        const reindexed = cols.map((col, idx) => ({
          ...col,
          order: idx,
        }));

        const nextState: FieldCustomizationState = {
          ...prev,
          modules: {
            ...prev.modules,
            [moduleId]: {
              ...moduleCfg,
              columns: reindexed,
            },
          },
          updatedAt: new Date().toISOString(),
        };

        persistState(nextState);
        return nextState;
      });
    },
    [persistState],
  );

  const moveColumnUp = useCallback(
    (moduleId: string, columnId: string) => {
      setCustomizationState((prev) => {
        const moduleCfg = prev.modules[moduleId] || DEFAULT_FIELD_CUSTOMIZATIONS.modules[moduleId];
        if (!moduleCfg) return prev;

        const sorted = [...moduleCfg.columns].sort((a, b) => (a.order ?? 0) - (b.order ?? 0));
        const idx = sorted.findIndex((c) => c.id === columnId);
        if (idx <= 0) return prev;

        const target = sorted[idx];
        const previous = sorted[idx - 1];
        sorted[idx - 1] = target;
        sorted[idx] = previous;

        const reindexed = sorted.map((col, i) => ({ ...col, order: i }));

        const nextState: FieldCustomizationState = {
          ...prev,
          modules: {
            ...prev.modules,
            [moduleId]: {
              ...moduleCfg,
              columns: reindexed,
            },
          },
          updatedAt: new Date().toISOString(),
        };

        persistState(nextState);
        return nextState;
      });
    },
    [persistState],
  );

  const moveColumnDown = useCallback(
    (moduleId: string, columnId: string) => {
      setCustomizationState((prev) => {
        const moduleCfg = prev.modules[moduleId] || DEFAULT_FIELD_CUSTOMIZATIONS.modules[moduleId];
        if (!moduleCfg) return prev;

        const sorted = [...moduleCfg.columns].sort((a, b) => (a.order ?? 0) - (b.order ?? 0));
        const idx = sorted.findIndex((c) => c.id === columnId);
        if (idx < 0 || idx >= sorted.length - 1) return prev;

        const target = sorted[idx];
        const next = sorted[idx + 1];
        sorted[idx + 1] = target;
        sorted[idx] = next;

        const reindexed = sorted.map((col, i) => ({ ...col, order: i }));

        const nextState: FieldCustomizationState = {
          ...prev,
          modules: {
            ...prev.modules,
            [moduleId]: {
              ...moduleCfg,
              columns: reindexed,
            },
          },
          updatedAt: new Date().toISOString(),
        };

        persistState(nextState);
        return nextState;
      });
    },
    [persistState],
  );

  const setModuleDensity = useCallback(
    (moduleId: string, density: TableDensity) => {
      setCustomizationState((prev) => {
        const moduleCfg = prev.modules[moduleId] || DEFAULT_FIELD_CUSTOMIZATIONS.modules[moduleId];
        if (!moduleCfg) return prev;

        const nextState: FieldCustomizationState = {
          ...prev,
          modules: {
            ...prev.modules,
            [moduleId]: {
              ...moduleCfg,
              density,
            },
          },
          updatedAt: new Date().toISOString(),
        };

        persistState(nextState);
        return nextState;
      });
    },
    [persistState],
  );

  const setModuleSort = useCallback(
    (moduleId: string, sortBy: string, sortOrder: 'asc' | 'desc') => {
      setCustomizationState((prev) => {
        const moduleCfg = prev.modules[moduleId] || DEFAULT_FIELD_CUSTOMIZATIONS.modules[moduleId];
        if (!moduleCfg) return prev;

        const nextState: FieldCustomizationState = {
          ...prev,
          modules: {
            ...prev.modules,
            [moduleId]: {
              ...moduleCfg,
              defaultSortBy: sortBy,
              defaultSortOrder: sortOrder,
            },
          },
          updatedAt: new Date().toISOString(),
        };

        persistState(nextState);
        return nextState;
      });
    },
    [persistState],
  );

  const addCustomTag = useCallback(
    (tag: string) => {
      const clean = tag.trim();
      if (!clean) return;

      setCustomizationState((prev) => {
        if (prev.customTags.includes(clean)) return prev;
        const nextState: FieldCustomizationState = {
          ...prev,
          customTags: [...prev.customTags, clean],
          updatedAt: new Date().toISOString(),
        };
        persistState(nextState);
        return nextState;
      });
    },
    [persistState],
  );

  const removeCustomTag = useCallback(
    (tag: string) => {
      setCustomizationState((prev) => {
        const nextState: FieldCustomizationState = {
          ...prev,
          customTags: prev.customTags.filter((t) => t !== tag),
          updatedAt: new Date().toISOString(),
        };
        persistState(nextState);
        return nextState;
      });
    },
    [persistState],
  );

  const resetModuleToDefault = useCallback(
    async (moduleId?: string) => {
      let nextState: FieldCustomizationState;
      if (moduleId && DEFAULT_FIELD_CUSTOMIZATIONS.modules[moduleId]) {
        nextState = {
          ...customizationState,
          modules: {
            ...customizationState.modules,
            [moduleId]: DEFAULT_FIELD_CUSTOMIZATIONS.modules[moduleId],
          },
          updatedAt: new Date().toISOString(),
        };
      } else {
        nextState = {
          ...DEFAULT_FIELD_CUSTOMIZATIONS,
          updatedAt: new Date().toISOString(),
        };
      }
      setCustomizationState(nextState);
      await persistState(nextState);
    },
    [customizationState, persistState],
  );

  const getDensityClasses = useCallback((density: TableDensity = 'normal') => {
    switch (density) {
      case 'compact':
        return {
          pyTh: 'py-2 px-2.5',
          pyTd: 'py-1.5 px-2.5',
          textClass: 'text-[11px]',
        };
      case 'comfortable':
        return {
          pyTh: 'py-4 px-4',
          pyTd: 'py-3.5 px-4',
          textClass: 'text-xs',
        };
      case 'normal':
      default:
        return {
          pyTh: 'py-3 px-3.5',
          pyTd: 'py-2.5 px-3.5',
          textClass: 'text-xs',
        };
    }
  }, []);

  const value = useMemo(
    () => ({
      customizationState,
      isLoading,
      getModuleConfig,
      getVisibleColumns,
      isColumnVisible,
      toggleColumnVisibility,
      setColumnVisibility,
      updateColumn,
      reorderColumns,
      moveColumnUp,
      moveColumnDown,
      setModuleDensity,
      setModuleSort,
      addCustomTag,
      removeCustomTag,
      resetModuleToDefault,
      saveCustomizations,
      getDensityClasses,
    }),
    [
      customizationState,
      isLoading,
      getModuleConfig,
      getVisibleColumns,
      isColumnVisible,
      toggleColumnVisibility,
      setColumnVisibility,
      updateColumn,
      reorderColumns,
      moveColumnUp,
      moveColumnDown,
      setModuleDensity,
      setModuleSort,
      addCustomTag,
      removeCustomTag,
      resetModuleToDefault,
      saveCustomizations,
      getDensityClasses,
    ],
  );

  return <CustomizationContext.Provider value={value}>{children}</CustomizationContext.Provider>;
};

export const useCustomization = (): CustomizationContextType => {
  const context = useContext(CustomizationContext);
  if (!context) {
    throw new Error('useCustomization must be used within a CustomizationProvider');
  }
  return context;
};

export interface NavigationState {
  tab: 'DASHBOARD' | 'PLANS' | 'EXPLORER' | 'RUNS' | 'DEFECTS' | 'REPORTS' | 'SETTINGS';
  projectId: string | null;
  suiteId: string | null;
  caseId: string | null;
  runId?: string | null;
  planId?: string | null;
  label: string;
  timestamp?: number;
}

interface NavigationContextType {
  history: NavigationState[];
  currentIndex: number;
  currentState: NavigationState | null;
  canGoBack: boolean;
  canGoForward: boolean;
  previousState: NavigationState | null;
  nextState: NavigationState | null;
  pushState: (state: Omit<NavigationState, 'timestamp'>) => void;
  goBack: () => void;
  goForward: () => void;
  registerNavigationHandler: (handler: (state: NavigationState) => void) => () => void;
}

const NavigationContext = createContext<NavigationContextType | undefined>(undefined);

const MAX_HISTORY_LENGTH = 50;

export const NavigationProvider: React.FC<{ children: React.ReactNode }> = ({ children }) => {
  const [history, setHistory] = useState<NavigationState[]>([]);
  const [currentIndex, setCurrentIndex] = useState<number>(-1);

  // Synchronous refs to prevent any stale closure issues
  const historyRef = useRef<NavigationState[]>([]);
  const currentIndexRef = useRef<number>(-1);
  const isNavigatingRef = useRef(false);
  const navigationHandlerRef = useRef<((state: NavigationState) => void) | null>(null);

  const currentState = currentIndex >= 0 && currentIndex < history.length ? history[currentIndex] : null;

  // canGoBack is true if there is a previous history item OR if we are currently deep in Explorer/Suite/Case/Runs and can navigate back to Dashboard
  const canGoBack =
    currentIndex > 0 ||
    Boolean(currentState && (currentState.tab !== 'DASHBOARD' || currentState.suiteId || currentState.caseId || currentState.runId));

  const canGoForward = currentIndex >= 0 && currentIndex < history.length - 1;
  const previousState = currentIndex > 0 ? history[currentIndex - 1] : null;
  const nextState = canGoForward ? history[currentIndex + 1] : null;

  // Load history from localStorage on initial mount
  useEffect(() => {
    try {
      const savedHist = localStorage.getItem('tcms_nav_history');
      const savedIdx = localStorage.getItem('tcms_nav_index');
      if (savedHist && savedIdx !== null) {
        const parsed = JSON.parse(savedHist);
        const idx = parseInt(savedIdx, 10);
        if (Array.isArray(parsed) && parsed.length > 0 && idx >= 0 && idx < parsed.length) {
          historyRef.current = parsed;
          currentIndexRef.current = idx;
          setHistory(parsed);
          setCurrentIndex(idx);
        }
      }
    } catch {
      // Ignore
    }
  }, []);

  const persistNavHistory = (hist: NavigationState[], idx: number) => {
    try {
      localStorage.setItem('tcms_nav_history', JSON.stringify(hist));
      localStorage.setItem('tcms_nav_index', String(idx));
    } catch {
      // Ignore
    }
  };

  // Register state applicator from page.tsx
  const registerNavigationHandler = useCallback((handler: (state: NavigationState) => void) => {
    navigationHandlerRef.current = handler;
    return () => {
      navigationHandlerRef.current = null;
    };
  }, []);

  // Push new navigation state - completely synchronous via refs
  const pushState = useCallback((newState: Omit<NavigationState, 'timestamp'>) => {
    if (isNavigatingRef.current) return;

    const prevHistory = historyRef.current;
    const currentIdx = currentIndexRef.current;
    const currentItem = currentIdx >= 0 && currentIdx < prevHistory.length ? prevHistory[currentIdx] : null;

    // Avoid consecutive duplicate states
    if (
      currentItem &&
      currentItem.tab === newState.tab &&
      currentItem.projectId === newState.projectId &&
      currentItem.suiteId === newState.suiteId &&
      currentItem.caseId === newState.caseId &&
      currentItem.runId === newState.runId &&
      currentItem.planId === newState.planId
    ) {
      // If only the label updated (e.g. project name loaded), update current in place
      if (currentItem.label !== newState.label) {
        const updated = [...prevHistory];
        updated[currentIdx] = { ...currentItem, label: newState.label };
        historyRef.current = updated;
        setHistory(updated);
        persistNavHistory(updated, currentIdx);
      }
      return;
    }

    // Truncate any forward history if we were in the middle of the stack
    const validHistory = currentIdx >= 0 ? prevHistory.slice(0, currentIdx + 1) : [];
    const itemWithTime: NavigationState = {
      ...newState,
      timestamp: Date.now(),
    };

    const newHistory = [...validHistory, itemWithTime];
    if (newHistory.length > MAX_HISTORY_LENGTH) {
      newHistory.shift();
    }

    const newIndex = newHistory.length - 1;

    historyRef.current = newHistory;
    currentIndexRef.current = newIndex;

    setHistory(newHistory);
    setCurrentIndex(newIndex);
    persistNavHistory(newHistory, newIndex);
  }, []);

  // Go Back with Smart Fallback
  const goBack = useCallback(() => {
    const prevHistory = historyRef.current;
    const currentIdx = currentIndexRef.current;

    // 1. Standard History Back
    if (currentIdx > 0 && prevHistory.length > 1) {
      const targetIndex = currentIdx - 1;
      const targetState = prevHistory[targetIndex];

      if (targetState) {
        isNavigatingRef.current = true;
        currentIndexRef.current = targetIndex;
        setCurrentIndex(targetIndex);
        persistNavHistory(prevHistory, targetIndex);

        if (navigationHandlerRef.current) {
          navigationHandlerRef.current(targetState);
        }

        setTimeout(() => {
          isNavigatingRef.current = false;
        }, 150);
        return;
      }
    }

    // 2. Smart Contextual Fallback (e.g. after refresh when in Suite, Case, Plan, or non-Dashboard tab)
    const current = currentIdx >= 0 && currentIdx < prevHistory.length ? prevHistory[currentIdx] : null;
    if (navigationHandlerRef.current) {
      const fallbackState: NavigationState = {
        tab: current?.tab || 'DASHBOARD',
        projectId: current?.projectId || null,
        suiteId: null,
        caseId: null,
        runId: null,
        planId: null,
        label: current?.tab === 'PLANS' ? 'Test Planları' : current?.tab === 'EXPLORER' ? 'Test Senaryoları' : current?.tab === 'RUNS' ? 'Test Koşumları' : 'Dashboard',
        timestamp: Date.now(),
      };

      isNavigatingRef.current = true;
      navigationHandlerRef.current(fallbackState);

      const updatedHistory = [fallbackState];
      historyRef.current = updatedHistory;
      currentIndexRef.current = 0;
      setHistory(updatedHistory);
      setCurrentIndex(0);
      persistNavHistory(updatedHistory, 0);

      setTimeout(() => {
        isNavigatingRef.current = false;
      }, 150);
    }
  }, []);

  // Go Forward
  const goForward = useCallback(() => {
    const prevHistory = historyRef.current;
    const currentIdx = currentIndexRef.current;

    if (currentIdx >= 0 && currentIdx < prevHistory.length - 1) {
      const targetIndex = currentIdx + 1;
      const targetState = prevHistory[targetIndex];

      if (targetState) {
        isNavigatingRef.current = true;
        currentIndexRef.current = targetIndex;
        setCurrentIndex(targetIndex);
        persistNavHistory(prevHistory, targetIndex);

        if (navigationHandlerRef.current) {
          navigationHandlerRef.current(targetState);
        }

        setTimeout(() => {
          isNavigatingRef.current = false;
        }, 150);
      }
    }
  }, []);

  // Keyboard shortcut listener (Alt + Left Arrow for Back, Alt + Right Arrow for Forward)
  useEffect(() => {
    const handleKeyDown = (e: KeyboardEvent) => {
      const target = e.target as HTMLElement | null;
      const isInput =
        target &&
        (target.tagName === 'INPUT' ||
          target.tagName === 'TEXTAREA' ||
          target.tagName === 'SELECT' ||
          target.isContentEditable);

      if (e.altKey && e.key === 'ArrowLeft') {
        e.preventDefault();
        goBack();
      } else if (e.altKey && e.key === 'ArrowRight') {
        e.preventDefault();
        goForward();
      } else if (e.key === 'Backspace' && !isInput && !e.ctrlKey && !e.metaKey) {
        e.preventDefault();
        goBack();
      }
    };

    window.addEventListener('keydown', handleKeyDown);
    return () => window.removeEventListener('keydown', handleKeyDown);
  }, [goBack, goForward]);

  return (
    <NavigationContext.Provider
      value={{
        history,
        currentIndex,
        currentState,
        canGoBack,
        canGoForward,
        previousState,
        nextState,
        pushState,
        goBack,
        goForward,
        registerNavigationHandler,
      }}
    >
      {children}
    </NavigationContext.Provider>
  );
};

