        "status": "PASSED",
        "durationMs": 420
      },
      {
        "caseCode": "TC-102",
        "status": "FAILED",
        "durationMs": 1250,
        "errorMessage": "Element #submit-btn not found within 10s timeout",
        "jiraBugKey": "MOB-452"
      }
