            <label className="block text-xs font-semibold text-slate-300 mb-2">Hedef Platform</label>
            <div className="grid grid-cols-2 gap-3">
              <button
                type="button"
                onClick={() => {
                  setPlatform('iOS');
                  setDeviceAlias('iphone15');
                }}
                className={`flex items-center justify-center gap-2.5 py-3 rounded-xl border text-sm font-semibold transition-all ${
                  platform === 'iOS'
                    ? 'bg-purple-600/20 border-purple-500 text-white shadow-lg shadow-purple-900/30'
                    : 'bg-slate-800/40 border-slate-700 text-slate-400 hover:border-slate-600'
                }`}
              >
                <Smartphone className="w-4 h-4 text-purple-400" />
                <span>iOS (XCUITest / WDA)</span>
              </button>
              <button
                type="button"
                onClick={() => {
                  setPlatform('Android');
                  setDeviceAlias('s24');
                }}
                className={`flex items-center justify-center gap-2.5 py-3 rounded-xl border text-sm font-semibold transition-all ${
                  platform === 'Android'
                    ? 'bg-emerald-600/20 border-emerald-500 text-white shadow-lg shadow-emerald-900/30'
                    : 'bg-slate-800/40 border-slate-700 text-slate-400 hover:border-slate-600'
                }`}
              >
                <Smartphone className="w-4 h-4 text-emerald-400" />
                <span>Android (UiAutomator2)</span>
              </button>
            </div>
          </div>

          {/* Device Selection */}
          <div>
            <div className="flex items-center justify-between mb-1.5">
              <label className="text-xs font-semibold text-slate-300">Hedef Cihaz / Emülatör</label>
              <span className="text-[11px] text-slate-400">{filteredDevices.length} cihaz algılandı</span>
            </div>
            <div className="grid grid-cols-2 gap-2">
              {filteredDevices.length > 0 ? (
                filteredDevices.map((d) => (
                  <button
                    key={d.udid || d.alias}
                    type="button"
                    onClick={() => setDeviceAlias(d.alias || d.udid)}
                    className={`flex flex-col items-start p-3 rounded-xl border text-left transition-all ${
                      deviceAlias === (d.alias || d.udid)
                        ? 'bg-slate-800 border-purple-500 text-white shadow-md'
                        : 'bg-slate-950/40 border-slate-800 text-slate-400 hover:border-slate-700'
                    }`}
                  >
                    <div className="flex items-center justify-between w-full">
                      <span className="font-semibold text-xs text-slate-200">{d.name || d.alias}</span>
                      <span
                        className={`text-[10px] px-1.5 py-0.5 rounded font-mono ${
                          d.state === 'device' ? 'bg-emerald-500/10 text-emerald-400' : 'bg-slate-700 text-slate-400'
                        }`}
                      >
                        {d.alias}
                      </span>
                    </div>
                    <span className="text-[10px] font-mono text-slate-400 mt-1 truncate max-w-[200px]">
                      UDID: {d.udid}
                    </span>
                  </button>
                ))
              ) : (
                <div className="col-span-2 p-3 text-center text-xs text-slate-500 bg-slate-950/30 rounded-xl border border-slate-800">
                  Bağlı cihaz bulunamadı. Lütfen cihazı bağlayıp "Cihazları Tara" butonuna tıklayınız.
                </div>
              )}
            </div>
          </div>

          {/* Test Scope */}
          <div>
            <label className="block text-xs font-semibold text-slate-300 mb-1.5">Test Kapsamı (Scope)</label>
            <div className="grid grid-cols-4 gap-2">
              {[
                { id: 'ALL', label: 'Tümü' },
                { id: 'SUITE', label: 'Test Paketi' },
                { id: 'SELECTED_CASES', label: 'Case Kodları' },
                { id: 'SPECS', label: 'Spec Dosyaları' },
              ].map((item) => (
                <button
                  key={item.id}
                  type="button"
                  onClick={() => setScope(item.id as any)}
                  className={`py-2 rounded-lg text-xs font-medium border transition-all ${
                    scope === item.id
                      ? 'bg-purple-600 text-white border-purple-500 font-bold'
                      : 'bg-slate-800/40 border-slate-700 text-slate-400 hover:border-slate-600'
                  }`}
                >
                  {item.label}
                </button>
              ))}
            </div>

            {/* Scope Details */}
            {scope === 'SUITE' && (
              <div className="mt-3">
                <select
                  value={selectedSuiteId}
                  onChange={(e) => setSelectedSuiteId(e.target.value)}
                  className="w-full px-3 py-2 text-xs bg-slate-800 border border-slate-700 rounded-lg text-white focus:outline-none focus:border-purple-500"
                >
                  <option value="">-- Test Paketi Seçin --</option>
                  {suites.map((s) => (
                    <option key={s.id} value={s.id}>
                      {s.name}
                    </option>
                  ))}
                </select>
              </div>
            )}

            {scope === 'SELECTED_CASES' && (
              <div className="mt-3">
                <input
                  type="text"
                  value={customCaseCodes}
                  onChange={(e) => setCustomCaseCodes(e.target.value)}
                  placeholder="Örn: MOB-TC-1, MOB-TC-2, MOB-BENEFICIARY-1"
                  className="w-full px-3 py-2 text-xs bg-slate-800 border border-slate-700 rounded-lg text-white focus:outline-none focus:border-purple-500"
                />
                <p className="text-[11px] text-slate-400 mt-1">Virgülle ayırarak case kodlarını giriniz.</p>
              </div>
            )}

            {scope === 'SPECS' && (
              <div className="mt-3 space-y-2 max-h-40 overflow-y-auto p-2 bg-slate-950/50 rounded-xl border border-slate-800">
                {specs.length > 0 ? (
                  specs.map((s) => (
                    <label
                      key={s.relativePath}
                      className="flex items-center gap-2 text-xs text-slate-300 hover:text-white cursor-pointer select-none p-1 rounded hover:bg-slate-800/50"
                    >
                      <input
                        type="checkbox"
                        checked={selectedSpecs.includes(s.relativePath)}
                        onChange={() => handleToggleSpec(s.relativePath)}
                        className="rounded border-slate-700 text-purple-600 focus:ring-0 bg-slate-800"
                      />
                      <FileCode className="w-3.5 h-3.5 text-purple-400 shrink-0" />
                      <span className="font-mono text-[11px] truncate">{s.name}</span>
                      <span className="text-[10px] text-slate-400 ml-auto">({s.cases.length} case)</span>
                    </label>
                  ))
                ) : (
                  <p className="text-xs text-slate-400 text-center py-2">TAC'tan spec listesi yüklenemedi.</p>
                )}
              </div>
            )}
          </div>

          {/* Environment & Version & Title */}
          <div className="grid grid-cols-2 gap-3">
            <div>
              <label className="block text-xs font-semibold text-slate-300 mb-1">Test Ortamı</label>
              <select
                value={environment}
                onChange={(e) => setEnvironment(e.target.value)}
                className="w-full px-3 py-2 text-xs bg-slate-800 border border-slate-700 rounded-lg text-white focus:outline-none focus:border-purple-500"
              >
                <option value="UAT">UAT</option>
                <option value="STAGING">STAGING</option>
                <option value="DEV">DEV</option>
                <option value="PROD">PROD</option>
              </select>
            </div>
            <div>
              <label className="block text-xs font-semibold text-slate-300 mb-1">Uygulama Versiyonu</label>
              <input
                type="text"
                value={version}
                onChange={(e) => setVersion(e.target.value)}
                className="w-full px-3 py-2 text-xs bg-slate-800 border border-slate-700 rounded-lg text-white focus:outline-none focus:border-purple-500 font-mono"
              />
            </div>
          </div>

          {/* Webhook Endpoint */}
          <div>
            <label className="block text-xs font-semibold text-slate-300 mb-1">TAC Webhook Alıcı Adresi</label>
            <input
              type="text"
              value={webhookUrl}
              onChange={(e) => setWebhookUrl(e.target.value)}
              className="w-full px-3 py-2 text-xs bg-slate-800 border border-slate-700 rounded-lg text-white font-mono focus:outline-none focus:border-purple-500"
            />
          </div>
        </form>

        {/* Footer */}
        <div className="flex items-center justify-between px-6 py-4 bg-slate-950/80 border-t border-slate-800">
          <button
            type="button"
            onClick={onClose}
            className="px-4 py-2 text-xs font-semibold text-slate-300 hover:text-white transition-colors"
          >
            İptal
          </button>
          <button
            type="button"
            onClick={handleSubmit}
            disabled={isSubmitting}
            className="flex items-center gap-2 px-5 py-2 text-xs font-bold text-white bg-gradient-to-r from-purple-600 to-indigo-600 hover:from-purple-500 hover:to-indigo-500 rounded-xl shadow-lg shadow-purple-900/40 transition-all disabled:opacity-50"
          >
            {isSubmitting ? (
              <>
                <RefreshCw className="w-4 h-4 animate-spin" />
                <span>Tetikleniyor...</span>
              </>
            ) : (
              <>
                <Play className="w-4 h-4 fill-current" />
                <span>⚡ Otomasyonu Başlat & Canlı İzle</span>
              </>
            )}
          </button>
        </div>
      </div>
    </div>
  );
};

export const NewProjectModal: React.FC<NewProjectModalProps> = ({
  isOpen,
  onClose,
  onSubmit,
}) => {
  const [name, setName] = useState('');
  const [key, setKey] = useState('');
  const [description, setDescription] = useState('');
  const [jiraProjectKey, setJiraProjectKey] = useState('');
  const [errorMsg, setErrorMsg] = useState('');
  const [isSubmitting, setIsSubmitting] = useState(false);

  if (!isOpen) return null;

  const handleSubmit = async (e: React.FormEvent) => {
    e.preventDefault();
    if (!name.trim() || !key.trim()) return;

    setIsSubmitting(true);
    setErrorMsg('');
    try {
      await onSubmit({
        name: name.trim(),
        key: key.trim().toUpperCase(),
        description: description.trim() || undefined,
        jiraProjectKey: jiraProjectKey.trim().toUpperCase() || undefined,
      });
      setName('');
      setKey('');
      setDescription('');
      setJiraProjectKey('');
      setErrorMsg('');
      onClose();
    } catch (err: any) {
      console.error(err);
      const message = err?.response?.data?.message || err?.message || 'Test Projesi oluşturulurken bir hata oluştu.';
      setErrorMsg(Array.isArray(message) ? message.join(', ') : message);
    } finally {
      setIsSubmitting(false);
    }
  };

  return (
    <div className="fixed inset-0 z-50 bg-black/60 backdrop-blur-sm flex items-center justify-center p-4">
      <div className="bg-white dark:bg-slate-900 border border-slate-200 dark:border-slate-800 rounded-2xl w-full max-w-md shadow-2xl overflow-hidden animate-scaleUp text-slate-800 dark:text-slate-100">
        <div className="px-6 py-4 border-b border-slate-200 dark:border-slate-800 flex items-center justify-between bg-slate-50 dark:bg-slate-900/80">
          <div className="flex items-center space-x-2.5">
            <FolderKanban className="w-5 h-5 text-[var(--accent-primary)]" />
            <h3 className="text-sm font-bold text-slate-800 dark:text-slate-100">Yeni Test Projesi Oluştur</h3>
          </div>
          <button onClick={onClose} className="text-slate-400 hover:text-slate-700 dark:hover:text-white p-1 rounded-lg">
            <X className="w-4 h-4" />
          </button>
        </div>

        {errorMsg && (
          <div className="mx-6 mt-4 p-3 bg-rose-500/10 border border-rose-500/30 rounded-xl text-xs text-rose-500 font-medium">
            {errorMsg}
          </div>
        )}

        <form onSubmit={handleSubmit} className="p-6 space-y-4">
          <div className="space-y-1.5">
            <label className="text-xs font-semibold text-slate-700 dark:text-slate-300">Test Projesi Adı</label>
            <input
              type="text"
              required
              placeholder="Örn: E-Commerce Web & Mobil"
              value={name}
              onChange={(e) => {
                setName(e.target.value);
                if (!key) {
                  const suggested = e.target.value
                    .replace(/[^a-zA-Z0-9]/g, '')
                    .substring(0, 4)
                    .toUpperCase();
                  setKey(suggested);
                }
              }}
              className="w-full bg-slate-50 dark:bg-slate-900 border border-slate-200 dark:border-slate-800 rounded-xl px-3.5 py-2 text-xs text-slate-800 dark:text-slate-200 focus:outline-none focus:ring-1 focus:ring-[var(--accent-primary)] shadow-sm"
            />
          </div>

          <div className="grid grid-cols-2 gap-3">
            <div className="space-y-1.5">
              <label className="text-xs font-semibold text-slate-700 dark:text-slate-300">
                Proje Kodu / Key (Ön Ek)
              </label>
              <input
                type="text"
                required
                maxLength={10}
                placeholder="Örn: PRJ"
                value={key}
                onChange={(e) => setKey(e.target.value.toUpperCase())}
                className="w-full bg-slate-50 dark:bg-slate-900 border border-slate-200 dark:border-slate-800 rounded-xl px-3.5 py-2 text-xs font-mono font-bold text-[var(--accent-primary)] focus:outline-none focus:ring-1 focus:ring-[var(--accent-primary)] uppercase shadow-sm"
              />
            </div>

            <div className="space-y-1.5">
              <label className="text-xs font-semibold text-slate-700 dark:text-slate-300">
                Jira Proje Kodu (Opsiyonel)
              </label>
              <input
                type="text"
                maxLength={10}
                placeholder="Örn: MOB veya PRJ"
                value={jiraProjectKey}
                onChange={(e) => setJiraProjectKey(e.target.value.toUpperCase())}
                className="w-full bg-slate-50 dark:bg-slate-900 border border-slate-200 dark:border-slate-800 rounded-xl px-3.5 py-2 text-xs font-mono font-bold text-blue-600 dark:text-blue-400 focus:outline-none focus:ring-1 focus:ring-blue-500 uppercase shadow-sm"
              />
            </div>
          </div>

          <span className="block text-[10px] text-slate-500">
            Test Case'leriniz {key || 'KEY'}-TC-1, {key || 'KEY'}-TC-2 biçiminde otomatik kodlanacaktır.
          </span>

          <div className="space-y-1.5">
            <label className="text-xs font-semibold text-slate-700 dark:text-slate-300">Açıklama</label>
            <textarea
              rows={3}
              placeholder="Test projesi hedefi, kapsamı ve detayları..."
              value={description}
              onChange={(e) => setDescription(e.target.value)}
              className="w-full bg-slate-50 dark:bg-slate-900 border border-slate-200 dark:border-slate-800 rounded-xl px-3.5 py-2 text-xs text-slate-800 dark:text-slate-200 focus:outline-none focus:ring-1 focus:ring-[var(--accent-primary)] resize-none shadow-sm"
            />
          </div>

          <div className="flex items-center justify-end space-x-3 pt-3">
            <button
              type="button"
              onClick={onClose}
              className="px-4 py-2 bg-slate-100 dark:bg-slate-800 hover:bg-slate-200 dark:hover:bg-slate-700 text-slate-700 dark:text-slate-300 text-xs font-semibold rounded-xl border border-slate-200 dark:border-slate-700"
            >
              İptal
            </button>

            <button
              type="submit"
              disabled={isSubmitting || !name.trim() || !key.trim()}
              className="flex items-center space-x-2 px-5 py-2 bg-accent-gradient hover:brightness-110 text-white text-xs font-semibold rounded-xl shadow-md shadow-[var(--accent-dark)]/20 active:scale-95 transition-all disabled:opacity-50 cursor-pointer"
            >
              <Plus className="w-4 h-4" />
              <span>{isSubmitting ? 'Oluşturuluyor...' : 'Test Projesi Oluştur'}</span>
            </button>
          </div>
        </form>
      </div>
    </div>
  );
};

export const ReportsView: React.FC<ReportsViewProps> = ({
  project,
}) => {
  const { role } = useAuth();

  // Role-based initial view mode: Admins and Viewers default to EXECUTIVE, Testers can switch
  const [viewMode, setViewMode] = useState<'EXECUTIVE' | 'QA'>(() => {
    if (typeof window !== 'undefined') {
      const saved = localStorage.getItem('tcms_report_view_mode');
      if (saved === 'EXECUTIVE' || saved === 'QA') return saved;
    }
    return role === 'ADMIN' || role === 'VIEWER' ? 'EXECUTIVE' : 'EXECUTIVE';
  });

  const [qaSubTab, setQaSubTab] = useState<'RUNS' | 'DEFECTS' | 'CASES'>('RUNS');
  const [loading, setLoading] = useState(false);
  const [summary, setSummary] = useState<ProjectReportSummary | null>(null);
  const [selectedRunId, setSelectedRunId] = useState<string | null>(null);
  const [runSummary, setRunSummary] = useState<RunReportSummary | null>(null);
  const [loadingRun, setLoadingRun] = useState(false);
  const [searchQuery, setSearchQuery] = useState('');
  const [filterPriority, setFilterPriority] = useState<string>('ALL');
  const [filterStatus, setFilterStatus] = useState<string>('ALL');
  const [exportingFormat, setExportingFormat] = useState<string | null>(null);

  const handleSetViewMode = (mode: 'EXECUTIVE' | 'QA') => {
    setViewMode(mode);
    if (typeof window !== 'undefined') {
      localStorage.setItem('tcms_report_view_mode', mode);
    }
  };

  // Load project report data
  const loadProjectReport = useCallback(async () => {
    if (!project) return;
    setLoading(true);
    try {
      const data = await ReportsService.getProjectSummary(project.id);
      setSummary(data);
      if (data.recentRuns && data.recentRuns.length > 0 && !selectedRunId) {
        setSelectedRunId(data.recentRuns[0].id);
      }
    } catch (err) {
      console.error('Failed to load project report:', err);
    } finally {
      setLoading(false);
    }
  }, [project, selectedRunId]);

  useEffect(() => {
    loadProjectReport();
  }, [project, loadProjectReport]);

  // Load selected test run summary
  const loadRunReport = useCallback(async (runId: string) => {
    setLoadingRun(true);
    try {
      const data = await ReportsService.getRunSummary(runId);
      setRunSummary(data);
    } catch (err) {
      console.error('Failed to load run report:', err);
    } finally {
      setLoadingRun(false);
    }
  }, []);

  useEffect(() => {
    if (selectedRunId) {
      loadRunReport(selectedRunId);
    }
  }, [selectedRunId, loadRunReport]);

  // Quick export triggers
  const handleExport = async (format: 'json' | 'csv' | 'html') => {
    if (!project) return;
    setExportingFormat(format);
    try {
      await ReportsService.downloadProjectReport(project.id, format, project.key);
    } catch (err) {
      console.error('Export failed:', err);
      alert('Rapor indirilirken bir hata oluştu.');
    } finally {
      setExportingFormat(null);
    }
  };

  const handleExportRun = async (runId: string, format: 'json' | 'csv' | 'html', title: string) => {
    setExportingFormat(`run-${format}`);
    try {
      await ReportsService.downloadRunReport(runId, format, title);
    } catch (err) {
      console.error('Run export failed:', err);
      alert('Koşum raporu indirilirken bir hata oluştu.');
    } finally {
      setExportingFormat(null);
    }
  };

  const handlePrint = () => {
    if (!project) return;
    const url = ReportsService.getProjectExportUrl(project.id, 'html');
    const win = window.open(url, '_blank');
    if (win) {
      win.focus();
    }
  };

  if (!project) {
    return (
      <div className="flex-1 flex flex-col items-center justify-center p-12 text-slate-400 dark:text-slate-500">
        <FileText className="w-16 h-16 mb-4 opacity-30 animate-pulse" />
        <p className="text-lg font-medium">Lütfen bir Test Projesi seçin</p>
        <p className="text-sm text-slate-500 mt-1">Raporları ve analitik dökümleri görüntülemek için üst menüden bir test projesi seçin.</p>
      </div>
    );
  }

  const metrics = summary?.metrics || {
    totalCases: 0,
    totalSuites: 0,
    totalRuns: 0,
    passed: 0,
    failed: 0,
    blocked: 0,
    skipped: 0,
    untested: 0,
    executedTotal: 0,
    passRate: 0,
    executedPassRate: 0,
  };

  const readiness = summary?.readiness || {
    status: 'GO',
    score: metrics.passRate,
    reason: 'Kalite eşikleri sağlandı.',
    blockerCount: 0,
    criticalCount: 0,
  };

  const channels = summary?.channels || [
    { key: 'MOBILE', name: 'Mobil Bankacılık (iOS / Android)', icon: 'Smartphone', total: 0, passed: 0, failed: 0, blocked: 0, untested: 0, passRate: 0 },
    { key: 'WEB', name: 'Web İnternet Şubesi', icon: 'Globe', total: 0, passed: 0, failed: 0, blocked: 0, untested: 0, passRate: 0 },
    { key: 'API', name: 'Ana Bankacılık Gtech API', icon: 'Zap', total: 0, passed: 0, failed: 0, blocked: 0, untested: 0, passRate: 0 },
    { key: 'DESKTOP', name: 'Ana Bankacılık Masaüstü / Gişe', icon: 'Monitor', total: 0, passed: 0, failed: 0, blocked: 0, untested: 0, passRate: 0 },
  ];

  const automation = summary?.automation || {
