              {importResult && (
                <div
                  className={`p-3.5 rounded-xl flex items-center space-x-2.5 text-xs font-semibold ${
                    importResult.success
                      ? 'bg-emerald-500/10 text-emerald-700 dark:text-emerald-300 border border-emerald-500/20'
