                          onClick={() => onStartRunWithPlan(plan)}
                          className="text-blue-600 dark:text-blue-400 font-bold hover:underline cursor-pointer"
                        >
                          Detayları Gör &rarr;
                        </button>
                      </div>
                    </div>
                  ))}
                </div>
              ) : (
                <div className="py-16 text-center text-slate-400">
                  <PlayCircle className="w-8 h-8 mx-auto mb-2 opacity-30 text-slate-400" />
                  <p className="font-semibold text-slate-700 dark:text-slate-300">
                    Bu test planı ile henüz bir test koşumu yürütülmedi.
                  </p>
                  <p className="text-[11px] text-slate-400 mt-1 mb-4">
                    İlk test koşumunu başlatarak senaryoları test edin ve sonuçları kaydedin.
                  </p>
                  <button
                    type="button"
                    onClick={() => onStartRunWithPlan(plan, planCases)}
                    className="inline-flex items-center space-x-1.5 px-4 py-2 rounded-xl text-xs font-bold text-white bg-emerald-600 hover:bg-emerald-700 shadow-xs cursor-pointer"
                  >
                    <Play className="w-3.5 h-3.5 fill-current" />
                    <span>Test Koşumu Başlat</span>
                  </button>
                </div>
              )}
            </div>
          )}
        </div>
      </div>

      {/* Modal: Add Existing Cases to Plan (Multi-Select Supported) */}
      {isAddCasesModalOpen && (
        <div className="fixed inset-0 bg-black/50 backdrop-blur-xs z-50 flex items-center justify-center p-4">
          <div className="w-full max-w-3xl bg-white dark:bg-[#161f30] rounded-2xl border border-slate-200 dark:border-slate-700 shadow-2xl overflow-hidden flex flex-col max-h-[88vh] animate-in fade-in zoom-in-95 duration-150">
            {/* Modal Header */}
            <div className="p-4 px-5 border-b border-slate-100 dark:border-slate-800 flex items-center justify-between bg-slate-50/40 dark:bg-[#121926]/40">
              <div>
                <h3 className="text-sm font-bold text-slate-900 dark:text-slate-100 flex items-center gap-2">
                  <FolderKanban className="w-4 h-4 text-[var(--accent-primary)]" />
                  <span>Test Planına Senaryoları Ekle</span>
                </h3>
                <p className="text-xs text-slate-500 dark:text-slate-400 mt-0.5">
                  Proje havuzundaki mevcut test senaryolarını seçerek bu test planına dahil edin.
                </p>
              </div>
              <button
                type="button"
                onClick={() => setIsAddCasesModalOpen(false)}
                className="p-1.5 rounded-lg text-slate-400 hover:text-slate-600 dark:hover:text-slate-200 hover:bg-slate-100 dark:hover:bg-slate-800 transition-colors cursor-pointer"
              >
                <X className="w-4 h-4" />
              </button>
            </div>

            {/* Filter Toolbar */}
            <div className="p-3 px-5 border-b border-slate-100 dark:border-slate-800 bg-slate-50/60 dark:bg-[#121926]/60 flex flex-col sm:flex-row gap-2.5">
              {/* Search */}
              <div className="relative flex-1">
                <Search className="w-3.5 h-3.5 text-slate-400 absolute left-3 top-1/2 -translate-y-1/2" />
                <input
                  type="text"
                  placeholder="Senaryo adı, kod veya açıklama ara..."
                  value={candidateSearchQuery}
                  onChange={(e) => setCandidateSearchQuery(e.target.value)}
                  className="w-full bg-white dark:bg-[#1d232f] border border-slate-200 dark:border-slate-700 rounded-xl pl-9 pr-4 py-1.5 text-xs text-slate-900 dark:text-slate-100 placeholder-slate-400 focus:outline-none focus:ring-1 focus:ring-blue-500"
                />
              </div>

              {/* Module Filter */}
              {availableSuites.length > 0 && (
                <select
                  value={candidateSuiteFilter}
                  onChange={(e) => setCandidateSuiteFilter(e.target.value)}
                  className="bg-white dark:bg-[#1d232f] border border-slate-200 dark:border-slate-700 rounded-xl px-2.5 py-1.5 text-xs text-slate-700 dark:text-slate-300 focus:outline-none font-medium"
                >
                  <option value="ALL">Tüm Modüller</option>
                  {availableSuites.map((s) => (
                    <option key={s.id} value={s.id}>
                      {s.name}
                    </option>
                  ))}
                </select>
              )}

              {/* Priority Filter */}
              <select
                value={candidatePriorityFilter}
                onChange={(e) => setCandidatePriorityFilter(e.target.value)}
                className="bg-white dark:bg-[#1d232f] border border-slate-200 dark:border-slate-700 rounded-xl px-2.5 py-1.5 text-xs text-slate-700 dark:text-slate-300 focus:outline-none font-medium"
              >
                <option value="ALL">Tüm Öncelikler</option>
                <option value="BLOCKER">Blocker</option>
                <option value="CRITICAL">Critical</option>
                <option value="NORMAL">Normal</option>
                <option value="LOW">Low</option>
              </select>

              {/* Type Filter */}
              <select
                value={candidateTypeFilter}
                onChange={(e) => setCandidateTypeFilter(e.target.value)}
                className="bg-white dark:bg-[#1d232f] border border-slate-200 dark:border-slate-700 rounded-xl px-2.5 py-1.5 text-xs text-slate-700 dark:text-slate-300 focus:outline-none font-medium"
              >
                <option value="ALL">Tüm Türler</option>
                <option value="WEB">Web</option>
                <option value="MOBILE">Mobile</option>
                <option value="API">API</option>
                <option value="PERFORMANCE">Performance</option>
              </select>
            </div>

            {/* Quick Multi-Select Action Bar */}
            <div className="px-5 py-2 bg-slate-100/60 dark:bg-[#182234] border-b border-slate-200/60 dark:border-slate-800 flex items-center justify-between text-xs">
              <div className="flex items-center space-x-2">
                <button
                  type="button"
                  onClick={isAllCandidatesSelected ? handleDeselectAllCandidates : handleSelectAllCandidates}
                  disabled={candidateCases.length === 0}
                  className="inline-flex items-center space-x-1.5 px-2.5 py-1 rounded-lg font-semibold text-slate-700 dark:text-slate-200 bg-white dark:bg-[#1d232f] border border-slate-200 dark:border-slate-700 hover:bg-slate-50 dark:hover:bg-slate-800 disabled:opacity-40 transition-colors cursor-pointer shadow-xs"
                >
                  {isAllCandidatesSelected ? (
                    <>
                      <MinusSquare className="w-3.5 h-3.5 text-[var(--accent-primary)]" />
                      <span>Filtrelenenlerin Seçimini Kaldır</span>
                    </>
                  ) : (
                    <>
                      <CheckSquare className="w-3.5 h-3.5 text-blue-600" />
                      <span>Filtrelenenleri Tümünü Seç ({candidateCases.length})</span>
                    </>
                  )}
                </button>

                {candidateCaseIdsToAdd.length > 0 && (
                  <button
                    type="button"
                    onClick={() => setCandidateCaseIdsToAdd([])}
                    className="text-xs text-slate-500 hover:text-rose-600 transition-colors cursor-pointer underline ml-2"
                  >
                    Tüm Seçimleri Temizle
                  </button>
                )}
              </div>

              <div className="text-[11px] font-mono text-slate-500 dark:text-slate-400">
                <strong className="text-blue-600 dark:text-blue-400 font-bold">{candidateCaseIdsToAdd.length}</strong> seçili /{' '}
                <span>{candidateCases.length} aday</span>
              </div>
            </div>

            {/* Candidates List */}
            <div className="p-3 px-5 overflow-y-auto flex-1 max-h-96 space-y-2">
              {candidateCases.length === 0 ? (
                <div className="py-12 text-center text-slate-400">
                  <Folder className="w-7 h-7 mx-auto mb-2 opacity-30" />
                  <p className="font-semibold text-slate-700 dark:text-slate-300">
                    Eklenebilecek test senaryosu bulunamadı.
                  </p>
                  <p className="text-[11px] text-slate-400 mt-1">
                    Tüm mevcut senaryolar zaten plana dahil edilmiş veya arama filtrenizle eşleşen kayıt yok.
                  </p>
                </div>
              ) : (
                candidateCases.map((c) => {
                  const isChecked = candidateCaseIdsToAdd.includes(c.id);
                  return (
                    <div
                      key={c.id}
                      onClick={() =>
                        setCandidateCaseIdsToAdd((prev) =>
                          prev.includes(c.id) ? prev.filter((id) => id !== c.id) : [...prev, c.id]
                        )
                      }
                      className={`p-3 rounded-xl border flex items-center justify-between cursor-pointer transition-all ${
                        isChecked
                          ? 'bg-blue-50/90 dark:bg-blue-950/40 border-blue-500/50 shadow-xs'
                          : 'bg-white dark:bg-[#1d232f] border-slate-200/80 dark:border-slate-700/60 hover:border-slate-300 dark:hover:border-slate-600 hover:bg-slate-50/50 dark:hover:bg-slate-800/50'
                      }`}
                    >
                      <div className="flex items-center space-x-3 min-w-0 flex-1 pr-3">
                        <input
                          type="checkbox"
                          checked={isChecked}
                          onChange={() => {}}
                          className="rounded border-slate-300 text-[var(--accent-primary)] focus:ring-0 cursor-pointer h-4 w-4 shrink-0"
                        />
                        <span className="font-mono text-xs font-bold px-2 py-0.5 rounded-md bg-slate-100 dark:bg-slate-800 text-slate-800 dark:text-slate-200 border border-slate-200 dark:border-slate-700 shrink-0">
                          {c.code}
                        </span>
                        <div className="min-w-0 flex-1 truncate">
                          <p className="text-xs font-bold text-slate-900 dark:text-slate-100 truncate">
                            {c.title}
                          </p>
                          <div className="flex items-center space-x-2 text-[10px] text-slate-400 mt-0.5 truncate">
                            <span className="font-medium text-slate-600 dark:text-slate-300">
                              {c.suite?.name || 'Ana Modül'}
                            </span>
                            <span>&bull;</span>
                            <span
                              className={`font-bold px-1.5 py-0.2 rounded ${
                                c.priority === 'BLOCKER'
                                  ? 'text-rose-600 dark:text-rose-400 bg-rose-50 dark:bg-rose-950/60'
                                  : c.priority === 'CRITICAL'
                                  ? 'text-amber-600 dark:text-amber-400 bg-amber-50 dark:bg-amber-950/60'
                                  : 'text-slate-600 dark:text-slate-400 bg-slate-100 dark:bg-slate-800'
                              }`}
                            >
                              {c.priority}
                            </span>
                            <span>&bull;</span>
                            <span className="font-mono text-slate-500">{c.type}</span>
                            {c.steps && c.steps.length > 0 && (
                              <>
                                <span>&bull;</span>
                                <span>{c.steps.length} adım</span>
                              </>
                            )}
                          </div>
                        </div>
                      </div>
                    </div>
                  );
                })
              )}
            </div>

            {/* Modal Footer */}
            <div className="p-3 px-5 border-t border-slate-100 dark:border-slate-800 bg-slate-50/60 dark:bg-[#121926]/60 flex items-center justify-between text-xs">
              <span className="text-slate-600 dark:text-slate-400 font-medium">
                Toplam <strong>{candidateCaseIdsToAdd.length}</strong> senaryo seçildi
              </span>
              <div className="flex items-center space-x-2">
                <button
                  type="button"
                  onClick={() => setIsAddCasesModalOpen(false)}
                  className="px-3.5 py-1.5 rounded-xl font-semibold text-slate-600 dark:text-slate-400 hover:bg-slate-100 dark:hover:bg-slate-800 transition-colors cursor-pointer"
                >
                  İptal
                </button>
                <button
                  type="button"
                  disabled={candidateCaseIdsToAdd.length === 0}
                  onClick={handleConfirmAddCases}
                  className="inline-flex items-center space-x-1.5 px-4 py-1.5 rounded-xl font-bold text-white bg-accent-gradient hover:brightness-110 disabled:opacity-50 transition-all shadow-xs cursor-pointer"
                >
                  <Plus className="w-3.5 h-3.5" />
                  <span>Seçilenleri Plana Ekle ({candidateCaseIdsToAdd.length})</span>
                </button>
              </div>
            </div>
          </div>
        </div>
      )}
    </div>
  );
};

export const EditTestPlanModal: React.FC<EditTestPlanModalProps> = ({
  isOpen,
  onClose,
  plan,
  allCases = [],
  onUpdate,
  onDelete,
}) => {
  const [title, setTitle] = useState('');
  const [description, setDescription] = useState('');
  const [version, setVersion] = useState('v1.0.0');
  const [environment, setEnvironment] = useState('STAGING');
  const [status, setStatus] = useState<PlanStatus>('ACTIVE');
  const [scope, setScope] = useState('');
  const [requirements, setRequirements] = useState('');
  const [selectedCaseIds, setSelectedCaseIds] = useState<string[]>([]);
  const [caseSearchQuery, setCaseSearchQuery] = useState('');
  const [isSubmitting, setIsSubmitting] = useState(false);
  const [error, setError] = useState<string | null>(null);

  useEffect(() => {
    if (plan) {
      setTitle(plan.title || '');
      setDescription(plan.description || '');
      setVersion(plan.version || 'v1.0.0');
      setEnvironment(plan.environment || 'STAGING');
      setStatus(plan.status || 'ACTIVE');
      setScope(plan.scope || '');
      setRequirements(plan.requirements || '');

      try {
        const saved = localStorage.getItem(`tcms_plan_cases_${plan.id}`);
        if (saved !== null) {
          setSelectedCaseIds(JSON.parse(saved));
        } else {
          setSelectedCaseIds([]);
        }
      } catch {
        setSelectedCaseIds([]);
      }
    }
  }, [plan]);

  if (!isOpen || !plan) return null;

  const filteredCases = allCases.filter((c) => {
    if (!caseSearchQuery) return true;
    const q = caseSearchQuery.toLowerCase();
    return (
      c.title.toLowerCase().includes(q) ||
      c.code.toLowerCase().includes(q) ||
      (c.suite?.name && c.suite.name.toLowerCase().includes(q))
    );
  });

  const toggleCaseSelection = (id: string) => {
    setSelectedCaseIds((prev) =>
      prev.includes(id) ? prev.filter((item) => item !== id) : [...prev, id]
    );
  };

  const handleSelectAllCases = () => {
    setSelectedCaseIds(filteredCases.map((c) => c.id));
  };

  const handleClearSelectedCases = () => {
    setSelectedCaseIds([]);
  };

  const handleSubmit = async (e: React.FormEvent) => {
    e.preventDefault();
    if (!title.trim()) {
      setError('Test planı başlığı zorunludur');
      return;
    }

    try {
      setIsSubmitting(true);
      setError(null);

      // Save case IDs to localStorage
      try {
        localStorage.setItem(`tcms_plan_cases_${plan.id}`, JSON.stringify(selectedCaseIds));
      } catch {
        // Ignore
      }

      await onUpdate(plan.id, {
        title: title.trim(),
        description: description.trim() || undefined,
        version: version.trim() || 'v1.0.0',
        environment: environment.trim() || 'STAGING',
        status,
        scope: scope.trim() || undefined,
        requirements: requirements.trim() || undefined,
        caseIds: selectedCaseIds,
      });
      onClose();
    } catch (err: any) {
      console.error(err);
      setError(err?.response?.data?.message || 'Test planı güncellenirken bir hata oluştu');
    } finally {
      setIsSubmitting(false);
    }
  };

  const handleDelete = async () => {
    if (!onDelete) return;
    if (confirm(`'${plan.title}' adlı Test Planını silmek istediğinize emin misiniz?`)) {
      try {
        setIsSubmitting(true);
        await onDelete(plan.id);
        onClose();
      } catch (err: any) {
        console.error(err);
        setError(err?.response?.data?.message || 'Test planı silinirken bir hata oluştu');
      } finally {
        setIsSubmitting(false);
      }
    }
  };

  return (
    <div className="fixed inset-0 z-50 flex items-center justify-center p-4 bg-slate-950/70 backdrop-blur-md animate-in fade-in duration-150">
      <div className="w-full max-w-2xl rounded-2xl bg-white dark:bg-[#1d232f] border border-slate-200 dark:border-slate-700 shadow-2xl overflow-hidden flex flex-col max-h-[92vh]">
        {/* Modal Header */}
        <div className="p-4 sm:p-5 border-b border-slate-100 dark:border-slate-800 flex items-center justify-between bg-slate-50/50 dark:bg-[#141821]/50">
          <div className="flex items-center space-x-3">
            <div className="w-10 h-10 rounded-xl bg-accent-gradient text-white flex items-center justify-center shadow-md shadow-[var(--accent-dark)]/20">
              <ClipboardList className="w-5 h-5" />
            </div>
            <div>
              <h2 className="text-base font-bold text-slate-900 dark:text-slate-100">
                Test Planını Düzenle
              </h2>
              <p className="text-xs text-slate-500 dark:text-slate-400 font-mono">
                ID: {plan.id.slice(0, 8)}...
              </p>
            </div>
          </div>
          <button
            type="button"
            onClick={onClose}
            className="p-1.5 rounded-xl hover:bg-slate-200 dark:hover:bg-slate-800 text-slate-400 hover:text-slate-600 dark:hover:text-slate-200 transition-colors cursor-pointer"
          >
            <X className="w-4 h-4" />
          </button>
        </div>

        {/* Modal Body */}
        <form onSubmit={handleSubmit} className="p-5 overflow-y-auto space-y-4 flex-1">
          {error && (
            <div className="p-3 rounded-xl bg-rose-500/10 border border-rose-500/30 text-rose-600 dark:text-rose-400 text-xs font-medium">
              {error}
            </div>
          )}

          {/* Plan Title */}
          <div>
            <label className="block text-xs font-bold uppercase tracking-wider text-slate-600 dark:text-slate-400 mb-1.5">
              Plan Başlığı <span className="text-rose-500">*</span>
            </label>
            <input
              type="text"
              required
              value={title}
              onChange={(e) => setTitle(e.target.value)}
              className="w-full bg-slate-50 dark:bg-slate-800/80 border border-slate-200 dark:border-slate-700 rounded-xl px-3.5 py-2 text-xs font-medium text-slate-900 dark:text-slate-100 focus:outline-none focus:ring-2 focus:ring-[var(--accent-primary)]/30 focus:border-[var(--accent-primary)]"
            />
          </div>

          {/* Version & Environment & Status */}
          <div className="grid grid-cols-1 sm:grid-cols-3 gap-3">
            <div>
              <label className="block text-xs font-bold uppercase tracking-wider text-slate-600 dark:text-slate-400 mb-1.5">
                Hedef Sürüm
              </label>
              <div className="relative">
                <Tag className="w-3.5 h-3.5 text-slate-400 absolute left-3 top-1/2 -translate-y-1/2" />
                <input
                  type="text"
                  value={version}
                  onChange={(e) => setVersion(e.target.value)}
                  className="w-full bg-slate-50 dark:bg-slate-800/80 border border-slate-200 dark:border-slate-700 rounded-xl pl-9 pr-3 py-2 text-xs font-mono font-medium text-slate-900 dark:text-slate-100 focus:outline-none focus:ring-2 focus:ring-[var(--accent-primary)]/30"
                />
              </div>
            </div>

            <div>
              <label className="block text-xs font-bold uppercase tracking-wider text-slate-600 dark:text-slate-400 mb-1.5">
                Hedef Ortam
              </label>
              <div className="relative">
                <Server className="w-3.5 h-3.5 text-slate-400 absolute left-3 top-1/2 -translate-y-1/2" />
                <select
                  value={environment}
                  onChange={(e) => setEnvironment(e.target.value)}
                  className="w-full bg-slate-50 dark:bg-slate-800/80 border border-slate-200 dark:border-slate-700 rounded-xl pl-9 pr-3 py-2 text-xs font-semibold text-slate-900 dark:text-slate-100 focus:outline-none focus:ring-2 focus:ring-[var(--accent-primary)]/30"
                >
                  <option value="STAGING">STAGING</option>
                  <option value="UAT">UAT</option>
                  <option value="PROD">PROD (Canlı)</option>
                  <option value="DEV">DEV</option>
                  <option value="TEST">TEST</option>
                </select>
              </div>
            </div>

            <div>
              <label className="block text-xs font-bold uppercase tracking-wider text-slate-600 dark:text-slate-400 mb-1.5">
                Plan Durumu
              </label>
              <select
                value={status}
                onChange={(e) => setStatus(e.target.value as PlanStatus)}
                className="w-full bg-slate-50 dark:bg-slate-800/80 border border-slate-200 dark:border-slate-700 rounded-xl px-3 py-2 text-xs font-semibold text-slate-900 dark:text-slate-100 focus:outline-none focus:ring-2 focus:ring-[var(--accent-primary)]/30"
              >
                <option value="ACTIVE">AKTİF</option>
                <option value="DRAFT">TASLAK</option>
                <option value="COMPLETED">TAMAMLANDI</option>
                <option value="ARCHIVED">ARŞİV</option>
              </select>
            </div>
          </div>

          {/* Scope / Components */}
          <div>
            <label className="block text-xs font-bold uppercase tracking-wider text-slate-600 dark:text-slate-400 mb-1.5">
              Kapsam & Bileşenler (Yapı Taşları)
            </label>
            <div className="relative">
              <Layers className="w-3.5 h-3.5 text-slate-400 absolute left-3 top-2.5" />
              <input
                type="text"
                value={scope}
                onChange={(e) => setScope(e.target.value)}
                className="w-full bg-slate-50 dark:bg-slate-800/80 border border-slate-200 dark:border-slate-700 rounded-xl pl-9 pr-3 py-2 text-xs text-slate-900 dark:text-slate-100 focus:outline-none focus:ring-2 focus:ring-[var(--accent-primary)]/30"
              />
            </div>
          </div>

          {/* Requirements / Jira Stories */}
          <div>
            <label className="block text-xs font-bold uppercase tracking-wider text-slate-600 dark:text-slate-400 mb-1.5">
              Gereksinimler & Jira Hikayeleri
            </label>
            <div className="relative">
              <FileText className="w-3.5 h-3.5 text-slate-400 absolute left-3 top-2.5" />
              <input
                type="text"
                value={requirements}
                onChange={(e) => setRequirements(e.target.value)}
                className="w-full bg-slate-50 dark:bg-slate-800/80 border border-slate-200 dark:border-slate-700 rounded-xl pl-9 pr-3 py-2 text-xs text-slate-900 dark:text-slate-100 focus:outline-none focus:ring-2 focus:ring-[var(--accent-primary)]/30 font-mono"
              />
            </div>
          </div>

          {/* Description */}
          <div>
            <label className="block text-xs font-bold uppercase tracking-wider text-slate-600 dark:text-slate-400 mb-1.5">
              Plan Açıklaması & Test Stratejisi
            </label>
            <textarea
              rows={2}
              value={description}
              onChange={(e) => setDescription(e.target.value)}
              className="w-full bg-slate-50 dark:bg-slate-800/80 border border-slate-200 dark:border-slate-700 rounded-xl p-3 text-xs text-slate-900 dark:text-slate-100 focus:outline-none focus:ring-2 focus:ring-[var(--accent-primary)]/30"
            />
          </div>

          {/* Scenario Selection Section */}
          <div className="pt-2 border-t border-slate-100 dark:border-slate-800 space-y-2.5">
            <div className="flex items-center justify-between">
              <div>
                <label className="text-xs font-bold uppercase tracking-wider text-slate-700 dark:text-slate-300 block">
                  Plana Dahil Test Senaryoları
                </label>
                <span className="text-[11px] text-slate-400">
                  {selectedCaseIds.length} senaryo seçili
                </span>
              </div>
              <div className="flex items-center space-x-2">
                <button
                  type="button"
                  onClick={handleSelectAllCases}
                  disabled={filteredCases.length === 0}
                  className="text-[11px] font-semibold text-blue-600 hover:text-blue-700 dark:text-blue-400 hover:underline disabled:opacity-40 cursor-pointer"
                >
                  Tümünü Seç
                </button>
                <span className="text-slate-300 dark:text-slate-600">&bull;</span>
                <button
                  type="button"
                  onClick={handleClearSelectedCases}
                  disabled={selectedCaseIds.length === 0}
                  className="text-[11px] font-semibold text-rose-600 hover:text-rose-700 dark:text-rose-400 hover:underline disabled:opacity-40 cursor-pointer"
                >
                  Seçimi Temizle
                </button>
              </div>
            </div>

            {/* Case Search */}
            <div className="relative">
              <Search className="w-3.5 h-3.5 text-slate-400 absolute left-3 top-1/2 -translate-y-1/2" />
              <input
                type="text"
                placeholder="Senaryo başlığı veya koduyla ara..."
                value={caseSearchQuery}
                onChange={(e) => setCaseSearchQuery(e.target.value)}
                className="w-full bg-slate-50 dark:bg-slate-800/60 border border-slate-200 dark:border-slate-700 rounded-xl pl-9 pr-3 py-1.5 text-xs text-slate-900 dark:text-slate-100 placeholder-slate-400 focus:outline-none focus:ring-2 focus:ring-[var(--accent-primary)]/30"
              />
            </div>

            {/* Scenario Checklist Box */}
            <div className="max-h-48 overflow-y-auto border border-slate-200 dark:border-slate-700/80 rounded-xl divide-y divide-slate-100 dark:divide-slate-800 bg-slate-50/40 dark:bg-slate-900/40 p-1">
              {filteredCases.length === 0 ? (
                <div className="py-6 text-center text-xs text-slate-400">
                  {allCases.length === 0
                    ? 'Projede henüz test senaryosu bulunmuyor.'
                    : 'Aramaya uygun test senaryosu bulunamadı.'}
                </div>
              ) : (
                filteredCases.map((tc) => {
                  const isChecked = selectedCaseIds.includes(tc.id);
                  return (
                    <div
                      key={tc.id}
                      onClick={() => toggleCaseSelection(tc.id)}
                      className={`p-2 rounded-lg flex items-center justify-between cursor-pointer transition-colors ${
                        isChecked
                          ? 'bg-blue-50/80 dark:bg-blue-900/25 border border-blue-500/30'
                          : 'hover:bg-slate-100 dark:hover:bg-slate-800/60 border border-transparent'
                      }`}
                    >
                      <div className="flex items-center space-x-2.5 min-w-0 flex-1 pr-2">
                        <div
                          className={`w-4 h-4 rounded flex items-center justify-center shrink-0 border transition-colors ${
                            isChecked
                              ? 'bg-blue-600 border-blue-600 text-white'
                              : 'border-slate-300 dark:border-slate-600 bg-white dark:bg-slate-800'
                          }`}
                        >
                          {isChecked && <Check className="w-3 h-3 stroke-[3]" />}
                        </div>
                        <span className="font-mono text-xs font-bold px-1.5 py-0.5 rounded bg-slate-100 dark:bg-slate-800 text-slate-700 dark:text-slate-300 shrink-0">
                          {tc.code}
                        </span>
                        <div className="min-w-0 flex-1 truncate">
                          <p className="text-xs font-medium text-slate-800 dark:text-slate-200 truncate">
                            {tc.title}
                          </p>
                          <p className="text-[10px] text-slate-400 truncate">
                            {tc.suite?.name || 'Kök Dizin'} &bull; {tc.priority} &bull; {tc.type}
                          </p>
                        </div>
                      </div>
                    </div>
                  );
                })
              )}
            </div>
          </div>

          {/* Footer Actions */}
          <div className="pt-3 border-t border-slate-100 dark:border-slate-800 flex items-center justify-between">
            {onDelete ? (
              <button
                type="button"
                onClick={handleDelete}
                className="inline-flex items-center space-x-1.5 px-3 py-2 rounded-xl text-xs font-semibold text-rose-600 hover:bg-rose-500/10 transition-colors cursor-pointer"
              >
                <Trash2 className="w-3.5 h-3.5" />
                <span>Planı Sil</span>
              </button>
            ) : <div />}

            <div className="flex items-center space-x-2.5">
              <button
                type="button"
                onClick={onClose}
                className="px-4 py-2 rounded-xl text-xs font-semibold text-slate-600 dark:text-slate-300 hover:bg-slate-100 dark:hover:bg-slate-800 transition-colors cursor-pointer"
              >
                Vazgeç
              </button>
              <button
                type="submit"
                disabled={isSubmitting}
                className="inline-flex items-center justify-center gap-2 px-5 py-2 text-xs font-bold text-white transition-all duration-200 rounded-xl bg-accent-gradient hover:brightness-110 shadow-md shadow-[var(--accent-dark)]/25 active:scale-98 disabled:opacity-50 cursor-pointer"
              >
                <Save className="w-3.5 h-3.5" />
                <span>{isSubmitting ? 'Kaydediliyor...' : 'Değişiklikleri Kaydet'}</span>
              </button>
            </div>
          </div>
        </form>
      </div>
    </div>
  );
};

export const TestPlansView: React.FC<TestPlansViewProps> = ({
  project,
  projects = [],
  allCases = [],
  testPlans,
  onStartRunWithPlan,
  onSelectPlanToView,
  onNavigateToRuns,
  onOpenNewPlan,
  onPlansChange,
}) => {
  const { can } = useAuth();
  const { pushState } = useNavigation();
  const { getVisibleColumns, getModuleConfig, getDensityClasses } = useCustomization();
  const visibleCols = getVisibleColumns('test-plans');
  const moduleConfig = getModuleConfig('test-plans');
  const densityCls = getDensityClasses(moduleConfig.density);

  const [plans, setPlans] = useState<TestPlan[]>(testPlans || []);
  const [isLoading, setIsLoading] = useState(false);
  const [activeTab, setActiveTab] = useState<TabType>('ALL');
  const [statusDropdownFilter, setStatusDropdownFilter] = useState<string>('ALL');
  const [isFilterDropdownOpen, setIsFilterDropdownOpen] = useState(false);

  // Pagination State
  const [rowsPerPage, setRowsPerPage] = useState<number>(10);
  const [currentPage, setCurrentPage] = useState<number>(1);

  // Modals
  const [isNewPlanOpen, setIsNewPlanOpen] = useState(false);
  const [isEditPlanOpen, setIsEditPlanOpen] = useState(false);
  const [selectedPlanForEdit, setSelectedPlanForEdit] = useState<TestPlan | null>(null);
  const [isImportModalOpen, setIsImportModalOpen] = useState(false);

  // Synchronize when testPlans prop changes
  useEffect(() => {
    if (testPlans !== undefined) {
      setPlans(testPlans);
    }
  }, [testPlans]);

  // Load Plans
  const loadPlans = useCallback(async () => {
    if (!project?.id) return;
    if (onPlansChange) {
      await onPlansChange();
      return;
    }
    setIsLoading(true);
    try {
      const data = await TestPlansService.getAllByProject(project.id);
      setPlans(data || []);
    } catch (err) {
      console.error('Failed to load test plans:', err);
      setPlans([]);
    } finally {
      setIsLoading(false);
    }
  }, [project?.id, onPlansChange]);

  useEffect(() => {
    if (testPlans === undefined) {
      loadPlans();
    }
  }, [loadPlans, testPlans]);

  // Handle plan create
  const handleCreatePlan = async (data: CreateTestPlanDto & { caseIds?: string[] }) => {
    const created = await TestPlansService.create(data);
    if (created?.id) {
      try {
        localStorage.setItem(`tcms_plan_cases_${created.id}`, JSON.stringify(data.caseIds || []));
      } catch {
        // Ignore
      }
    }
    await loadPlans();
  };

  // Handle plan update
  const handleUpdatePlan = async (id: string, data: UpdateTestPlanDto & { caseIds?: string[] }) => {
    await TestPlansService.update(id, data);
    await loadPlans();
  };

  // Handle plan delete
  const handleDeletePlan = async (id: string) => {
    if (!confirm('Bu test planını silmek istediğinize emin misiniz?')) return;
    await TestPlansService.delete(id);
    await loadPlans();
  };

  // Helper to infer or calculate statistics for each plan
  const planStatsMap = useMemo(() => {
    const map = new Map<
      string,
      {
        type: string;
        typeColor: { bg: string; text: string; border: string };
        scope: string;
        totalScenarios: number;
        executedScenarios: number;
        passed: number;
        failed: number;
        blocked: number;
        skipped: number;
        passRate: number;
        lastRunDate: string;
        statusKey: 'ACTIVE' | 'IN_PROGRESS' | 'COMPLETED' | 'PASSIVE';
        dateRange: string;
      }
    >();

    plans.forEach((plan, idx) => {
      // 1. Infer Type
      let inferredType = 'Regression';
      const titleLower = (plan.title || '').toLowerCase();
      const descLower = (plan.description || '').toLowerCase();
      if (titleLower.includes('smoke') || descLower.includes('smoke')) {
        inferredType = 'Smoke';
      } else if (titleLower.includes('functional') || titleLower.includes('fonksiyonel') || descLower.includes('fonksiyonel')) {
        inferredType = 'Functional';
      } else if (titleLower.includes('api') || descLower.includes('api')) {
        inferredType = 'API';
      } else if (titleLower.includes('güvenlik') || titleLower.includes('security') || descLower.includes('güvenlik')) {
        inferredType = 'Security';
      } else if (titleLower.includes('performans') || titleLower.includes('performance') || descLower.includes('performans')) {
        inferredType = 'Performance';
      } else if (titleLower.includes('release') || titleLower.includes('sürüm')) {
        inferredType = 'Regression';
      }

      // Clean neutral slate type badge
      const typeColor = { bg: 'bg-slate-100 dark:bg-slate-800', text: 'text-slate-700 dark:text-slate-300', border: 'border-slate-200 dark:border-slate-700' };

      // 2. Scope
      let scopeText = plan.scope || 'Web, Mobil';
      if (!plan.scope) {
        if (inferredType === 'API') scopeText = 'API';
        else if (inferredType === 'Smoke') scopeText = 'Mobil';
        else if (inferredType === 'Security') scopeText = 'Web, Mobil, API';
        else if (inferredType === 'Performance') scopeText = 'Web, API';
        else scopeText = 'Web, Mobil';
      }

      // 3. Runs & Results metrics calculation from actual plan cases
      let planCaseIds: string[] = [];
      if (plan.cases && plan.cases.length > 0) {
        planCaseIds = plan.cases.map((c) => c.testCaseId);
      } else {
        try {
          const saved = localStorage.getItem(`tcms_plan_cases_${plan.id}`);
          if (saved !== null) {
            planCaseIds = JSON.parse(saved);
          }
        } catch {
          planCaseIds = [];
        }
      }

      let totalScenarios = plan._count?.cases !== undefined ? plan._count.cases : planCaseIds.length;
      if (totalScenarios === 0 && planCaseIds.length > 0) {
        totalScenarios = planCaseIds.length;
      }
      let executedScenarios = 0;
      let passed = 0;
      let failed = 0;
      let blocked = 0;
      let skipped = 0;
      let lastRunDate = '—';

      if (plan.testRuns && plan.testRuns.length > 0) {
        const latestRun = plan.testRuns[0];
        if (latestRun.createdAt) {
          lastRunDate = new Date(latestRun.createdAt).toLocaleString('tr-TR', {
            day: '2-digit',
            month: '2-digit',
            year: 'numeric',
            hour: '2-digit',
            minute: '2-digit',
          });
        }

        plan.testRuns.forEach((r) => {
          if (r.results) {
            r.results.forEach((res: any) => {
              if (totalScenarios === 0 || planCaseIds.includes(res.testCaseId)) {
                executedScenarios++;
                if (res.status === 'PASSED') passed++;
                else if (res.status === 'FAILED') failed++;
                else if (res.status === 'BLOCKED') blocked++;
                else if (res.status === 'SKIPPED') skipped++;
              }
            });
          }
        });
      }

      const passRate = executedScenarios > 0 ? Math.round((passed / executedScenarios) * 100) : 0;

      // Status mapping
      let statusKey: 'ACTIVE' | 'IN_PROGRESS' | 'COMPLETED' | 'PASSIVE' = 'ACTIVE';
      if (plan.status === 'COMPLETED') {
        statusKey = 'COMPLETED';
      } else if (plan.status === 'ARCHIVED' || plan.status === 'DRAFT') {
        statusKey = 'PASSIVE';
      } else {
        if (plan.title.toLowerCase().includes('ödeme') || plan.title.toLowerCase().includes('devam')) {
          statusKey = 'IN_PROGRESS';
        } else {
          statusKey = 'ACTIVE';
        }
      }

      // Date range formatting
      const createdDate = new Date(plan.createdAt || Date.now());
      const endDate = new Date(createdDate.getTime() + 18 * 24 * 60 * 60 * 1000);
      const dateRange = `${createdDate.toLocaleDateString('tr-TR', { day: '2-digit', month: '2-digit', year: 'numeric' })} - ${endDate.toLocaleDateString('tr-TR', { day: '2-digit', month: '2-digit', year: 'numeric' })}`;

      map.set(plan.id, {
        type: inferredType,
        typeColor,
        scope: scopeText,
        totalScenarios,
        executedScenarios,
        passed,
        failed,
        blocked,
        skipped,
        passRate,
        lastRunDate,
        statusKey,
        dateRange,
      });
    });

    return map;
  }, [plans, allCases]);

  // Overall KPI Card calculations
  const kpiData = useMemo(() => {
    const totalPlans = plans.length;
    let activeCount = 0;
    let inProgressCount = 0;
    let completedCount = 0;
    let passiveCount = 0;
    let totalRates = 0;
    let plansWithRuns = 0;

    plans.forEach((p) => {
      const stats = planStatsMap.get(p.id);
      if (stats) {
        if (stats.statusKey === 'ACTIVE') activeCount++;
        else if (stats.statusKey === 'IN_PROGRESS') inProgressCount++;
        else if (stats.statusKey === 'COMPLETED') completedCount++;
        else if (stats.statusKey === 'PASSIVE') passiveCount++;

        if (stats.executedScenarios > 0) {
          totalRates += stats.passRate;
          plansWithRuns++;
        }
      }
    });

    const avgPassRate = plansWithRuns > 0 ? Math.round(totalRates / plansWithRuns) : null;

    return {
      totalPlans,
      activeCount,
      passiveCount,
      inProgressCount,
      completedCount,
      avgPassRate,
    };
  }, [plans, planStatsMap]);

  // Filtered Plans based on active tab and status dropdown filter
  const filteredPlans = useMemo(() => {
    return plans.filter((p) => {
      const stats = planStatsMap.get(p.id);
      if (!stats) return true;

      // 1. Tab Filter
      if (activeTab === 'ACTIVE' && stats.statusKey !== 'ACTIVE') return false;
      if (activeTab === 'IN_PROGRESS' && stats.statusKey !== 'IN_PROGRESS') return false;
      if (activeTab === 'COMPLETED' && stats.statusKey !== 'COMPLETED') return false;
      if (activeTab === 'PASSIVE' && stats.statusKey !== 'PASSIVE') return false;

      // 2. Dropdown Filter
      if (statusDropdownFilter !== 'ALL' && stats.statusKey !== statusDropdownFilter) return false;

      return true;
    });
  }, [plans, planStatsMap, activeTab, statusDropdownFilter]);

  // Pagination slice
  const paginatedPlans = useMemo(() => {
    const startIndex = (currentPage - 1) * rowsPerPage;
    return filteredPlans.slice(startIndex, startIndex + rowsPerPage);
  }, [filteredPlans, currentPage, rowsPerPage]);

  const totalPages = Math.ceil(filteredPlans.length / rowsPerPage) || 1;

  if (!project) {
    return (
      <div className="flex-1 flex items-center justify-center p-6 text-slate-400">
        <div className="text-center space-y-3">
          <FolderKanban className="w-12 h-12 mx-auto text-slate-300 dark:text-slate-600" />
          <p className="text-sm font-medium">Lütfen üst menüden çalışılacak bir Test Projesi seçin.</p>
        </div>
      </div>
    );
  }

  return (
    <div className="flex-1 flex flex-col h-full overflow-y-auto bg-[#f8fafc] dark:bg-[#0b111e] select-none font-sans">
      {/* 1. Page Header: Title + Subtitle + Action Buttons */}
      <div className="px-6 pt-5 pb-4 shrink-0 flex flex-col sm:flex-row sm:items-center justify-between gap-4">
        <div>
          <h1 className="text-xl font-bold text-slate-900 dark:text-slate-100 tracking-tight">
            Test Planları
          </h1>
          <p className="text-xs text-slate-500 dark:text-slate-400 mt-0.5">
            Proje kapsamındaki test planlarını görüntüleyin ve yönetin.
          </p>
        </div>

        <div className="flex items-center flex-wrap gap-2 shrink-0">
          {/* Excel Actions Group */}
          <div className="flex items-center bg-white dark:bg-[#161f30] p-0.5 rounded-xl border border-slate-200 dark:border-slate-700/80 shadow-xs">
            <button
              type="button"
              onClick={downloadTestPlanTemplate}
              className="inline-flex items-center space-x-1.5 px-2.5 py-1.5 rounded-lg text-xs font-semibold text-slate-700 dark:text-slate-200 hover:bg-slate-50 dark:hover:bg-slate-800 transition-all cursor-pointer"
              title="Test Planı Excel Şablonunu İndir"
            >
              <Download className="w-3.5 h-3.5 text-emerald-600 dark:text-emerald-400" />
              <span className="hidden sm:inline">Şablon</span>
            </button>

            <button
              type="button"
              onClick={() => exportTestPlansToExcel(plans, project?.name || 'Proje')}
              disabled={plans.length === 0}
              className="inline-flex items-center space-x-1.5 px-2.5 py-1.5 rounded-lg text-xs font-semibold text-slate-700 dark:text-slate-200 hover:bg-slate-50 dark:hover:bg-slate-800 disabled:opacity-40 transition-all cursor-pointer"
              title="Test Planlarını Excel'e Aktar"
            >
              <FileSpreadsheet className="w-3.5 h-3.5 text-blue-600 dark:text-blue-400" />
              <span className="hidden sm:inline">Excel</span>
            </button>

            {project && can('CREATE_PLAN') && (
              <button
                type="button"
                onClick={() => setIsImportModalOpen(true)}
                className="inline-flex items-center space-x-1.5 px-2.5 py-1.5 rounded-lg text-xs font-semibold text-slate-700 dark:text-slate-200 hover:bg-slate-50 dark:hover:bg-slate-800 transition-all cursor-pointer"
                title="Excel Dosyasından Test Planı İçe Aktar"
              >
                <Upload className="w-3.5 h-3.5 text-indigo-600 dark:text-indigo-400" />
                <span>İçe Aktar</span>
              </button>
            )}
          </div>

          {/* Status Filter Dropdown */}
          <div className="relative">
            <button
              type="button"
              onClick={() => setIsFilterDropdownOpen((prev) => !prev)}
              className="inline-flex items-center space-x-2 px-3.5 py-2 rounded-xl text-xs font-semibold bg-white dark:bg-[#161f30] border border-slate-200 dark:border-slate-700/80 text-slate-700 dark:text-slate-200 hover:bg-slate-50 dark:hover:bg-slate-800 transition-all shadow-xs cursor-pointer"
            >
              <span>
                Durum:{' '}
                {statusDropdownFilter === 'ALL'
                  ? 'Tümü'
                  : statusDropdownFilter === 'ACTIVE'
                  ? 'Aktif'
                  : statusDropdownFilter === 'IN_PROGRESS'
                  ? 'Devam Eden'
                  : statusDropdownFilter === 'COMPLETED'
                  ? 'Tamamlandı'
                  : 'Pasif'}
              </span>
              <SlidersHorizontal className="w-3.5 h-3.5 text-slate-400" />
            </button>

            {isFilterDropdownOpen && (
              <div className="absolute right-0 mt-1.5 w-40 rounded-xl bg-white dark:bg-[#161f30] border border-slate-200 dark:border-slate-700 shadow-xl z-50 py-1 text-xs overflow-hidden">
                {[
                  { key: 'ALL', label: 'Tümü' },
                  { key: 'ACTIVE', label: 'Aktif' },
                  { key: 'IN_PROGRESS', label: 'Devam Eden' },
                  { key: 'COMPLETED', label: 'Tamamlandı' },
                  { key: 'PASSIVE', label: 'Pasif' },
                ].map((item) => (
                  <button
                    key={item.key}
                    type="button"
                    onClick={() => {
                      setStatusDropdownFilter(item.key);
                      setIsFilterDropdownOpen(false);
                    }}
                    className={`w-full text-left px-3 py-1.5 flex items-center justify-between hover:bg-slate-100 dark:hover:bg-slate-800 transition-colors ${
                      statusDropdownFilter === item.key
                        ? 'font-bold text-[var(--accent-primary)]'
                        : 'text-slate-700 dark:text-slate-300'
                    }`}
                  >
                    <span>{item.label}</span>
                    {statusDropdownFilter === item.key && <Check className="w-3.5 h-3.5 text-[var(--accent-primary)]" />}
                  </button>
                ))}
              </div>
            )}
          </div>

          {/* Column Customizer Dropdown */}
          <ColumnCustomizerMenu
            moduleId="test-plans"
            onOpenAdvancedSettings={() =>
              pushState({
                tab: 'SETTINGS',
                projectId: project?.id || null,
                suiteId: null,
                caseId: null,
                label: 'Alan Özelleştirme',
              })
            }
          />

          {/* New Test Plan Button */}
          <button
            type="button"
            onClick={() => (onOpenNewPlan ? onOpenNewPlan() : setIsNewPlanOpen(true))}
            className="inline-flex items-center space-x-2 px-4 py-2 rounded-xl text-xs font-bold text-white bg-accent-gradient hover:brightness-110 transition-all shadow-md shadow-[var(--accent-dark)]/25 active:scale-98 cursor-pointer"
          >
            <Plus className="w-4 h-4" />
            <span>Yeni Test Planı</span>
            <ChevronDown className="w-3.5 h-3.5 opacity-80" />
          </button>
        </div>
      </div>

      {/* 2. Top Metric Cards (Grid Row of 4 Compact Cards) */}
      <div className="px-6 py-3 shrink-0 grid grid-cols-1 sm:grid-cols-2 lg:grid-cols-4 gap-3">
        {/* Card 1: Toplam Test Planı */}
        <div className="py-2.5 px-3.5 rounded-xl bg-white dark:bg-[#161f30] border border-slate-200/80 dark:border-slate-700/60 shadow-xs flex items-center space-x-3">
          <div className="w-8 h-8 rounded-lg bg-blue-500/10 dark:bg-blue-500/15 text-blue-600 dark:text-blue-400 flex items-center justify-center shrink-0">
            <ClipboardList className="w-4 h-4" />
          </div>
          <div className="min-w-0 flex-1">
            <span className="text-[10px] font-bold text-slate-500 dark:text-slate-400 uppercase tracking-wider block">
              Toplam Test Planı
            </span>
            <div className="flex items-baseline space-x-1.5">
              <span className="text-lg font-black text-slate-900 dark:text-slate-100 leading-none">
                {kpiData.totalPlans}
              </span>
              <span className="text-[10px] text-slate-400 font-medium">Plan</span>
            </div>
          </div>
        </div>

        {/* Card 2: Aktif / Devam Eden */}
        <div className="py-2.5 px-3.5 rounded-xl bg-white dark:bg-[#161f30] border border-slate-200/80 dark:border-slate-700/60 shadow-xs flex items-center space-x-3">
          <div className="w-8 h-8 rounded-lg bg-emerald-500/10 dark:bg-emerald-500/15 text-emerald-600 dark:text-emerald-400 flex items-center justify-center shrink-0">
            <CheckCircle2 className="w-4 h-4" />
          </div>
          <div className="min-w-0 flex-1">
            <span className="text-[10px] font-bold text-slate-500 dark:text-slate-400 uppercase tracking-wider block">
              Aktif & Devam Eden
            </span>
            <div className="flex items-center space-x-1.5 text-sm font-black leading-none">
              <span className="text-emerald-700 dark:text-emerald-300 font-bold">{kpiData.activeCount} Aktif</span>
              <span className="text-slate-300 dark:text-slate-600 font-normal">&bull;</span>
              <span className="text-amber-700 dark:text-amber-300 font-bold">{kpiData.inProgressCount} Koşumda</span>
            </div>
          </div>
        </div>

        {/* Card 3: Tamamlanan Planlar */}
        <div className="py-2.5 px-3.5 rounded-xl bg-white dark:bg-[#161f30] border border-slate-200/80 dark:border-slate-700/60 shadow-xs flex items-center space-x-3">
          <div className="w-8 h-8 rounded-lg bg-purple-500/10 dark:bg-purple-500/15 text-purple-600 dark:text-purple-400 flex items-center justify-center shrink-0">
            <Calendar className="w-4 h-4" />
          </div>
          <div className="min-w-0 flex-1">
            <span className="text-[10px] font-bold text-slate-500 dark:text-slate-400 uppercase tracking-wider block">
              Tamamlanan Planlar
            </span>
            <div className="flex items-baseline space-x-1.5">
              <span className="text-lg font-black text-slate-900 dark:text-slate-100 leading-none">
                {kpiData.completedCount}
              </span>
              <span className="text-[10px] text-slate-400 font-medium">Başarılı</span>
            </div>
          </div>
        </div>

        {/* Card 4: Ortalama Başarı Oranı */}
        <div className="py-2.5 px-3.5 rounded-xl bg-white dark:bg-[#161f30] border border-slate-200/80 dark:border-slate-700/60 shadow-xs flex items-center space-x-3">
          <div className="w-8 h-8 rounded-lg bg-amber-500/10 dark:bg-amber-500/15 text-amber-600 dark:text-amber-400 flex items-center justify-center shrink-0">
            <AlertTriangle className="w-4 h-4" />
          </div>
          <div className="flex-1 min-w-0">
            <div className="flex items-center justify-between">
              <span className="text-[10px] font-bold text-slate-500 dark:text-slate-400 uppercase tracking-wider">
                Ort. Başarı Oranı
              </span>
              <span className="text-xs font-black text-slate-900 dark:text-slate-100">
                {kpiData.avgPassRate !== null ? `%${kpiData.avgPassRate}` : '—'}
              </span>
            </div>
            <div className="w-full bg-slate-100 dark:bg-slate-800 h-1.5 rounded-full mt-1 overflow-hidden">
              <div
                className={`h-full rounded-full ${
                  (kpiData.avgPassRate || 0) >= 75
                    ? 'bg-emerald-500'
                    : (kpiData.avgPassRate || 0) >= 50
                    ? 'bg-amber-500'
                    : 'bg-rose-500'
                }`}
                style={{ width: `${kpiData.avgPassRate || 0}%` }}
              />
            </div>
          </div>
        </div>
      </div>

      {/* 3. Main Data Grid Table (Full Width) */}
      <div className="min-w-0 px-6 pb-6 w-full flex-1 flex flex-col">
        <div className="w-full bg-white dark:bg-[#161f30] rounded-2xl border border-slate-200/80 dark:border-slate-700/60 shadow-xs overflow-hidden flex flex-col flex-1">
          {/* Tab Navigation */}
          <div className="flex items-center space-x-6 px-5 border-b border-slate-100 dark:border-slate-800 text-xs font-semibold">
            {[
              { key: 'ALL', label: 'Tümü' },
              { key: 'ACTIVE', label: 'Aktif' },
              { key: 'IN_PROGRESS', label: 'Devam Eden' },
              { key: 'COMPLETED', label: 'Tamamlandı' },
              { key: 'PASSIVE', label: 'Pasif' },
            ].map((tab) => {
              const isActive = activeTab === tab.key;
              return (
                <button
                  key={tab.key}
                  type="button"
                  onClick={() => {
                    setActiveTab(tab.key as TabType);
                    setCurrentPage(1);
                  }}
                  className={`py-3 border-b-2 transition-all cursor-pointer ${
                    isActive
                      ? 'border-[var(--accent-primary)] text-[var(--accent-primary)] font-bold'
                      : 'border-transparent text-slate-500 hover:text-slate-800 dark:text-slate-400 dark:hover:text-slate-200'
                  }`}
                >
                  {tab.label}
                </button>
              );
            })}
          </div>

          {/* Table Container */}
          <div className="overflow-x-auto flex-1">
            <table className="w-full text-left text-xs border-collapse min-w-full">
              <thead className="sticky top-0 z-10 bg-slate-100/90 dark:bg-[#1a2333] border-b border-slate-200 dark:border-slate-700/80 shadow-xs">
                <tr className="text-[11px] font-bold text-slate-700 dark:text-slate-200 uppercase tracking-wider">
                  {visibleCols.map((col) => (
                    <th
                      key={col.id}
                      style={{ width: col.width || 'auto' }}
                      className={`${densityCls.pyTh} whitespace-nowrap text-${col.align || 'left'}`}
                    >
                      {col.label}
                    </th>
                  ))}
                </tr>
              </thead>
              <tbody className="divide-y divide-slate-100 dark:divide-slate-800/60 font-medium">
                {isLoading ? (
                  <tr>
                    <td colSpan={visibleCols.length || 8} className="py-14 text-center text-slate-400">
                      <div className="w-6 h-6 border-2 border-[var(--accent-primary)]/20 border-t-[var(--accent-primary)] rounded-full animate-spin mx-auto mb-2" />
                      <span>Yükleniyor...</span>
                    </td>
                  </tr>
                ) : paginatedPlans.length === 0 ? (
                  <tr>
                    <td colSpan={visibleCols.length || 8} className="py-14 text-center text-slate-400">
                      <ClipboardList className="w-8 h-8 mx-auto mb-2 opacity-30 text-slate-400" />
                      <p>Kayıtlı test planı bulunamadı.</p>
                    </td>
                  </tr>
                ) : (
                  paginatedPlans.map((p) => {
                    const stats = planStatsMap.get(p.id);

                    return (
                      <tr
                        key={p.id}
                        onClick={() => {
                          if (onSelectPlanToView) {
                            onSelectPlanToView(p);
                          } else {
                            setSelectedPlanForEdit(p);
                            setIsEditPlanOpen(true);
                          }
                        }}
                        className="hover:bg-slate-50/80 dark:hover:bg-slate-800/40 transition-colors cursor-pointer group"
                      >
                        {visibleCols.map((col) => {
                          const alignClass = `text-${col.align || 'left'}`;

                          if (col.id === 'title') {
                            return (
                              <td key={col.id} className={`${densityCls.pyTd} min-w-0 max-w-[260px] whitespace-nowrap ${alignClass}`}>
                                <div className="flex items-center space-x-2.5 min-w-0">
                                  <div className="w-7 h-7 rounded-lg bg-blue-500/10 dark:bg-blue-500/15 text-blue-600 dark:text-blue-400 flex items-center justify-center shrink-0 group-hover:scale-105 transition-transform">
                                    <Calendar className="w-3.5 h-3.5" />
                                  </div>
                                  <div className="min-w-0 flex-1">
                                    <p className="font-bold text-slate-900 dark:text-slate-100 truncate group-hover:text-[var(--accent-primary)] transition-colors text-xs" title={p.title}>
                                      {p.title}
                                    </p>
                                    {p.description && (
                                      <p className="text-[10px] text-slate-400 dark:text-slate-500 truncate mt-0.5" title={p.description}>
                                        {p.description}
                                      </p>
                                    )}
                                  </div>
                                </div>
                              </td>
                            );
                          }

                          if (col.id === 'type') {
                            return (
                              <td key={col.id} className={`${densityCls.pyTd} w-[84px] min-w-[84px] whitespace-nowrap ${alignClass}`}>
                                <span
                                  className={`inline-flex items-center px-2 py-0.5 rounded-md text-[10px] font-bold border shadow-xs ${
                                    stats?.typeColor.bg || 'bg-slate-100 dark:bg-slate-800'
                                  } ${stats?.typeColor.text || 'text-slate-700 dark:text-slate-300'} ${
                                    stats?.typeColor.border || 'border-slate-200 dark:border-slate-700'
                                  }`}
                                >
                                  {stats?.type || 'Regression'}
                                </span>
                              </td>
                            );
                          }

                          if (col.id === 'scope') {
                            return (
                              <td key={col.id} className={`${densityCls.pyTd} min-w-0 max-w-[180px] whitespace-nowrap ${alignClass}`} title={stats?.scope || 'Web, Mobil'}>
                                <p className="truncate text-xs text-slate-600 dark:text-slate-400 font-medium">
                                  {stats?.scope || 'Web, Mobil'}
                                </p>
                              </td>
                            );
                          }

                          if (col.id === 'scenariosCount') {
                            return (
                              <td key={col.id} className={`${densityCls.pyTd} w-[76px] min-w-[76px] text-center font-bold text-slate-800 dark:text-slate-200 font-mono whitespace-nowrap`}>
                                {stats ? stats.totalScenarios : 0}
                              </td>
                            );
                          }

                          if (col.id === 'passRate') {
                            return (
                              <td key={col.id} className={`${densityCls.pyTd} w-[120px] min-w-[120px] whitespace-nowrap ${alignClass}`}>
                                {stats && stats.executedScenarios > 0 ? (
                                  <div className="flex items-center space-x-2 w-full">
                                    <span className="font-bold text-slate-900 dark:text-slate-100 font-mono text-[11px] shrink-0 w-8">
                                      %{stats.passRate}
                                    </span>
                                    <div className="flex-1 bg-slate-100 dark:bg-slate-800 h-1.5 rounded-full overflow-hidden">
                                      <div
                                        className={`h-full rounded-full ${
                                          stats.passRate >= 75
                                            ? 'bg-emerald-500'
                                            : stats.passRate >= 50
                                            ? 'bg-amber-500'
                                            : 'bg-rose-500'
                                        }`}
                                        style={{ width: `${stats.passRate}%` }}
                                      />
                                    </div>
                                  </div>
                                ) : (
                                  <span className="text-slate-400 font-mono text-[11px]">—</span>
                                )}
                              </td>
                            );
                          }

                          if (col.id === 'status') {
                            return (
                              <td key={col.id} className={`${densityCls.pyTd} w-[100px] min-w-[100px] whitespace-nowrap ${alignClass}`}>
                                {stats?.statusKey === 'ACTIVE' ? (
                                  <span className="inline-flex items-center px-2 py-0.5 rounded-full text-[10px] font-bold bg-emerald-100 dark:bg-emerald-950/80 text-emerald-700 dark:text-emerald-300 border border-emerald-300 dark:border-emerald-700/60 shadow-xs">
                                    Aktif
                                  </span>
                                ) : stats?.statusKey === 'IN_PROGRESS' ? (
                                  <span className="inline-flex items-center px-2 py-0.5 rounded-full text-[10px] font-bold bg-amber-100 dark:bg-amber-950/80 text-amber-800 dark:text-amber-300 border border-amber-300 dark:border-amber-700/60 shadow-xs">
                                    Devam Eden
                                  </span>
                                ) : stats?.statusKey === 'COMPLETED' ? (
                                  <span className="inline-flex items-center px-2 py-0.5 rounded-full text-[10px] font-bold bg-blue-100 dark:bg-blue-950/80 text-blue-700 dark:text-blue-300 border border-blue-300 dark:border-blue-700/60 shadow-xs">
                                    Tamamlandı
                                  </span>
                                ) : (
                                  <span className="inline-flex items-center px-2 py-0.5 rounded-full text-[10px] font-medium bg-slate-100 dark:bg-slate-800 text-slate-700 dark:text-slate-300 border border-slate-300 dark:border-slate-700 shadow-xs">
                                    Pasif
                                  </span>
                                )}
                              </td>
                            );
                          }

                          if (col.id === 'lastRun') {
                            return (
                              <td key={col.id} className={`${densityCls.pyTd} w-[130px] min-w-[130px] text-slate-500 dark:text-slate-400 text-[11px] font-mono whitespace-nowrap ${alignClass}`}>
                                {stats?.lastRunDate || '—'}
                              </td>
                            );
                          }

                          if (col.id === 'actions') {
                            return (
                              <td key={col.id} className={`${densityCls.pyTd} w-[90px] min-w-[90px] text-right whitespace-nowrap`} onClick={(e) => e.stopPropagation()}>
                                <div className="flex items-center justify-end space-x-1">
                                  {/* Koşum Başlat */}
                                  <button
                                    type="button"
                                    onClick={() => onStartRunWithPlan(p)}
                                    className="p-1 rounded-lg text-emerald-600 dark:text-emerald-400 hover:bg-emerald-50 dark:hover:bg-emerald-950/40 transition-colors cursor-pointer"
                                    title="Koşum Başlat"
                                    aria-label="Koşum Başlat"
                                  >
                                    <Play className="w-3.5 h-3.5 fill-current text-emerald-600 dark:text-emerald-400" />
                                  </button>

                                  {/* Düzenle */}
                                  <button
                                    type="button"
                                    onClick={() => {
                                      if (onSelectPlanToView) {
                                        onSelectPlanToView(p);
                                      } else {
                                        setSelectedPlanForEdit(p);
                                        setIsEditPlanOpen(true);
                                      }
                                    }}
                                    className="p-1 rounded-lg text-slate-500 hover:text-slate-700 dark:text-slate-400 dark:hover:text-slate-200 hover:bg-slate-100 dark:hover:bg-slate-800 transition-colors cursor-pointer"
                                    title="Planı Düzenle"
                                    aria-label="Planı Düzenle"
                                  >
                                    <Pencil className="w-3.5 h-3.5" />
                                  </button>

                                  {/* Sil */}
                                  {can('DELETE_PLAN') && (
                                    <button
                                      type="button"
                                      onClick={() => handleDeletePlan(p.id)}
                                      className="p-1 rounded-lg text-slate-400 hover:text-rose-600 dark:hover:text-rose-400 hover:bg-rose-50 dark:hover:bg-rose-950/40 transition-colors cursor-pointer"
                                      title="Planı Sil"
                                      aria-label="Planı Sil"
                                    >
                                      <Trash2 className="w-3.5 h-3.5" />
                                    </button>
                                  )}
                                </div>
                              </td>
                            );
                          }

                          return (
                            <td key={col.id} className={`${densityCls.pyTd} whitespace-nowrap ${alignClass}`}>
                              —
                            </td>
                          );
                        })}
                      </tr>
                    );
                  })
                )}
              </tbody>
            </table>
          </div>

          {/* Table Footer: Total Count + Rows Per Page + Pagination Controls */}
          <div className="p-3.5 px-5 border-t border-slate-100 dark:border-slate-800 bg-slate-50/40 dark:bg-[#121926]/40 flex flex-col sm:flex-row sm:items-center justify-between gap-3 text-xs text-slate-500 shrink-0">
            <span className="font-medium">
              Toplam {filteredPlans.length} kayıt
            </span>

            <div className="flex items-center space-x-4">
              {/* Rows Per Page */}
              <div className="flex items-center space-x-1.5">
                <span>Satır sayısı:</span>
                <select
                  value={rowsPerPage}
                  onChange={(e) => {
                    setRowsPerPage(Number(e.target.value));
                    setCurrentPage(1);
                  }}
                  className="bg-white dark:bg-[#161f30] border border-slate-200 dark:border-slate-700 rounded-lg px-2 py-1 text-xs text-slate-700 dark:text-slate-300 focus:outline-none"
                >
                  <option value={5}>5</option>
                  <option value={10}>10</option>
                  <option value={20}>20</option>
                  <option value={50}>50</option>
                </select>
              </div>

              {/* Page Buttons */}
              <div className="flex items-center space-x-1">
                <button
                  type="button"
                  disabled={currentPage === 1}
                  onClick={() => setCurrentPage((p) => Math.max(1, p - 1))}
                  className="p-1 rounded-lg border border-slate-200 dark:border-slate-700 bg-white dark:bg-[#161f30] hover:bg-slate-100 dark:hover:bg-slate-800 disabled:opacity-30 cursor-pointer"
                >
                  <ChevronLeft className="w-3.5 h-3.5" />
                </button>
                {Array.from({ length: totalPages }).map((_, i) => (
                  <button
                    key={i + 1}
                    type="button"
                    onClick={() => setCurrentPage(i + 1)}
                    className={`w-6 h-6 rounded-lg font-bold text-xs transition-colors cursor-pointer ${
                      currentPage === i + 1
                        ? 'bg-accent-gradient text-white shadow-xs'
                        : 'bg-white dark:bg-[#161f30] text-slate-700 dark:text-slate-300 border border-slate-200 dark:border-slate-700 hover:bg-slate-100 dark:hover:bg-slate-800'
                    }`}
                    style={currentPage === i + 1 ? { background: 'var(--accent-gradient)' } : undefined}
                  >
                    {i + 1}
                  </button>
                ))}
                <button
                  type="button"
                  disabled={currentPage === totalPages}
                  onClick={() => setCurrentPage((p) => Math.min(totalPages, p + 1))}
                  className="p-1 rounded-lg border border-slate-200 dark:border-slate-700 bg-white dark:bg-[#161f30] hover:bg-slate-100 dark:hover:bg-slate-800 disabled:opacity-30 cursor-pointer"
                >
                  <ChevronRight className="w-3.5 h-3.5" />
                </button>
                <button
                  type="button"
                  disabled={currentPage === totalPages}
                  onClick={() => setCurrentPage(totalPages)}
                  className="p-1 rounded-lg border border-slate-200 dark:border-slate-700 bg-white dark:bg-[#161f30] hover:bg-slate-100 dark:hover:bg-slate-800 disabled:opacity-30 cursor-pointer"
                >
                  <ChevronsRight className="w-3.5 h-3.5" />
                </button>
              </div>
            </div>
          </div>
        </div>
      </div>

      {/* Modals */}
      <NewTestPlanModal
        isOpen={isNewPlanOpen}
        onClose={() => setIsNewPlanOpen(false)}
        projectId={project.id}
        projectName={project.name}
        projectKey={project.key}
        allCases={allCases}
        onSubmit={handleCreatePlan}
      />

      <EditTestPlanModal
        isOpen={isEditPlanOpen}
        onClose={() => {
          setIsEditPlanOpen(false);
          setSelectedPlanForEdit(null);
        }}
        plan={selectedPlanForEdit}
        allCases={allCases}
        onUpdate={handleUpdatePlan}
        onDelete={handleDeletePlan}
      />

      {/* Excel Import Modal */}
      {project && (
        <ExcelImportModal
          isOpen={isImportModalOpen}
          type="TEST_PLANS"
          projectId={project.id}
          projectName={project.name}
          onClose={() => setIsImportModalOpen(false)}
          onSuccess={async () => {
            await loadPlans();
          }}
        />
      )}
    </div>
  );
};

export const DefectDetailModal: React.FC<DefectDetailModalProps> = ({
  isOpen,
  onClose,
  defect,
  onUpdateStatus,
  onUpdateDetails,
  onDelete,
  onNavigateToCase,
  onNavigateToRun,
}) => {
  const [isEditing, setIsEditing] = useState(false);
  const [title, setTitle] = useState('');
  const [description, setDescription] = useState('');
  const [severity, setSeverity] = useState<DefectSeverity>('MAJOR');
  const [status, setStatus] = useState<DefectStatus>('OPEN');
  const [environment, setEnvironment] = useState('STAGING');
  const [channel, setChannel] = useState('WEB');
  const [assignedTo, setAssignedTo] = useState('');
  const [jiraBugKey, setJiraBugKey] = useState('');
  const [jiraBugUrl, setJiraBugUrl] = useState('');
  const [resolutionNotes, setResolutionNotes] = useState('');
  const [isSaving, setIsSaving] = useState(false);
  const [isDeleting, setIsDeleting] = useState(false);
  const [showResolutionBox, setShowResolutionBox] = useState(false);
  const [pendingStatusChange, setPendingStatusChange] = useState<DefectStatus | null>(null);

  useEffect(() => {
    if (defect) {
      setTitle(defect.title);
      setDescription(defect.description || '');
      setSeverity(defect.severity);
      setStatus(defect.status);
      setEnvironment(defect.environment || 'STAGING');
      setChannel(defect.channel || 'WEB');
      setAssignedTo(defect.assignedTo || '');
      setJiraBugKey(defect.jiraBugKey || '');
      setJiraBugUrl(defect.jiraBugUrl || '');
      setResolutionNotes(defect.resolutionNotes || '');
      setIsEditing(false);
      setShowResolutionBox(false);
      setPendingStatusChange(null);
    }
  }, [defect]);

  if (!isOpen || !defect) return null;

  const getSeverityBadge = (sev: DefectSeverity) => {
    switch (sev) {
      case 'BLOCKER':
        return 'bg-red-500/15 text-red-700 dark:text-red-400 border-red-500/30';
      case 'CRITICAL':
        return 'bg-rose-500/15 text-rose-700 dark:text-rose-400 border-rose-500/30';
      case 'MAJOR':
        return 'bg-amber-500/15 text-amber-700 dark:text-amber-400 border-amber-500/30';
      case 'MINOR':
        return 'bg-blue-500/15 text-blue-700 dark:text-blue-400 border-blue-500/30';
      case 'TRIVIAL':
        return 'bg-slate-500/15 text-slate-700 dark:text-slate-400 border-slate-500/30';
    }
  };

  const getStatusBadge = (st: DefectStatus) => {
    switch (st) {
      case 'OPEN':
        return 'bg-rose-500/15 text-rose-700 dark:text-rose-400 border-rose-500/30';
      case 'IN_PROGRESS':
        return 'bg-amber-500/15 text-amber-700 dark:text-amber-400 border-amber-500/30';
      case 'RESOLVED':
        return 'bg-emerald-500/15 text-emerald-700 dark:text-emerald-400 border-emerald-500/30';
      case 'CLOSED':
        return 'bg-slate-500/15 text-slate-700 dark:text-slate-400 border-slate-500/30';
      case 'REOPENED':
        return 'bg-purple-500/15 text-purple-700 dark:text-purple-400 border-purple-500/30';
      case 'WONT_FIX':
        return 'bg-zinc-500/15 text-zinc-700 dark:text-zinc-400 border-zinc-500/30';
    }
  };

  const getStatusLabel = (st: DefectStatus) => {
    switch (st) {
      case 'OPEN':
        return 'AÇIK';
      case 'IN_PROGRESS':
        return 'İNCELENİYOR';
      case 'RESOLVED':
        return 'ÇÖZÜLDÜ';
      case 'CLOSED':
        return 'KAPATILDI';
      case 'REOPENED':
        return 'YENİDEN AÇILDI';
      case 'WONT_FIX':
        return 'DÜZELTİLMEYECEK';
    }
  };

  const handleQuickStatus = async (newStatus: DefectStatus) => {
    if (newStatus === 'RESOLVED' || newStatus === 'CLOSED' || newStatus === 'WONT_FIX') {
      setPendingStatusChange(newStatus);
      setShowResolutionBox(true);
      return;
    }

    try {
      setIsSaving(true);
      await onUpdateStatus(defect.id, newStatus);
    } finally {
      setIsSaving(false);
    }
  };

  const handleConfirmResolution = async () => {
    if (!pendingStatusChange) return;
    try {
      setIsSaving(true);
      await onUpdateStatus(defect.id, pendingStatusChange, resolutionNotes);
      setShowResolutionBox(false);
      setPendingStatusChange(null);
    } finally {
      setIsSaving(false);
    }
  };

  const handleSaveDetails = async () => {
    try {
      setIsSaving(true);
      await onUpdateDetails(defect.id, {
        title: title.trim(),
        description: description.trim() || undefined,
        severity,
        environment,
        channel,
        assignedTo: assignedTo.trim() || undefined,
        jiraBugKey: jiraBugKey.trim() || undefined,
        jiraBugUrl: jiraBugUrl.trim() || undefined,
        resolutionNotes: resolutionNotes.trim() || undefined,
      });
      setIsEditing(false);
    } finally {
      setIsSaving(false);
    }
  };

  const handleDelete = async () => {
    if (!window.confirm(`"${defect.key}: ${defect.title}" kaydını silmek istediğinize emin misiniz?`)) {
      return;
    }
    try {
      setIsDeleting(true);
      await onDelete(defect.id);
      onClose();
    } finally {
      setIsDeleting(false);
    }
  };

  return (
    <div className="fixed inset-0 z-50 flex items-center justify-center p-4 bg-slate-950/75 backdrop-blur-md animate-in fade-in duration-150">
