            />
          </div>

          {/* Filter Dropdowns */}
          <div className="flex items-center flex-wrap gap-2 text-xs">
            {/* Status Filter */}
            <select
              value={statusFilter}
              onChange={(e) => setStatusFilter(e.target.value as StatusFilter)}
              className="bg-slate-50 dark:bg-slate-950 border border-slate-200 dark:border-slate-800 text-slate-700 dark:text-slate-300 rounded-xl px-3 py-1.5 text-xs font-medium focus:outline-none focus:ring-1 focus:ring-rose-500 cursor-pointer"
            >
              <option value="ALL">Tüm Durumlar</option>
              <option value="PASSED">Passed</option>
              <option value="FAILED">Failed</option>
              <option value="BLOCKED">Blocked</option>
              <option value="UNTESTED">Untested</option>
            </select>

            {/* Priority Filter */}
            <select
              value={priorityFilter}
              onChange={(e) => setPriorityFilter(e.target.value)}
              className="bg-slate-50 dark:bg-slate-950 border border-slate-200 dark:border-slate-800 text-slate-700 dark:text-slate-300 rounded-xl px-3 py-1.5 text-xs font-medium focus:outline-none focus:ring-1 focus:ring-rose-500 cursor-pointer"
            >
              <option value="ALL">Tüm Öncelikler</option>
              <option value="BLOCKER">🔴 BLOCKER</option>
              <option value="CRITICAL">🟠 CRITICAL</option>
              <option value="NORMAL">🔵 NORMAL</option>
              <option value="LOW">⚪ LOW</option>
            </select>

            {/* Type Filter */}
            <select
              value={typeFilter}
              onChange={(e) => setTypeFilter(e.target.value)}
              className="bg-slate-50 dark:bg-slate-950 border border-slate-200 dark:border-slate-800 text-slate-700 dark:text-slate-300 rounded-xl px-3 py-1.5 text-xs font-medium focus:outline-none focus:ring-1 focus:ring-rose-500 cursor-pointer"
            >
              <option value="ALL">Tüm Tipler</option>
              <option value="WEB">🌐 WEB</option>
              <option value="MOBILE">📱 MOBILE</option>
              <option value="API">⚡ API</option>
              <option value="MANUAL">📋 MANUAL</option>
            </select>
          </div>
        </div>

        {/* Global/Default Suite Run Settings Banner */}
        <div className="flex flex-col sm:flex-row sm:items-center justify-between gap-3 p-3 bg-rose-500/5 dark:bg-rose-500/10 border border-rose-500/20 rounded-2xl text-xs">
          <div className="flex items-center space-x-2">
            <Settings2 className="w-4 h-4 text-rose-500 shrink-0" />
            <span className="font-semibold text-slate-800 dark:text-slate-200">Varsayılan Koşu Parametreleri:</span>
            <span className="text-[11px] text-slate-500 dark:text-slate-400 hidden md:inline">
              (Liste satırları için genel versiyon ve ortam şablonu)
            </span>
          </div>

          <div className="flex items-center flex-wrap gap-2">
            <div className="flex items-center space-x-1.5 bg-white dark:bg-slate-900 px-2 py-1 rounded-xl border border-slate-200 dark:border-slate-800">
              <span className="text-[11px] text-slate-500 font-medium">Versiyon:</span>
              <input
                type="text"
                value={defaultVersion}
                onChange={(e) => setDefaultVersion(e.target.value)}
                placeholder="v1.0.0"
                className="w-20 bg-transparent text-xs font-mono font-bold text-slate-800 dark:text-slate-200 focus:outline-none"
              />
            </div>

            <div className="flex items-center space-x-1.5 bg-white dark:bg-slate-900 px-2 py-1 rounded-xl border border-slate-200 dark:border-slate-800">
              <span className="text-[11px] text-slate-500 font-medium">Ortam:</span>
              <select
                value={defaultEnvironment}
                onChange={(e) => setDefaultEnvironment(e.target.value)}
                className="bg-transparent text-xs font-bold text-slate-800 dark:text-slate-200 focus:outline-none cursor-pointer"
              >
                {PRESET_ENVIRONMENTS.map((env) => (
                  <option key={env} value={env}>
                    {env}
                  </option>
                ))}
              </select>
            </div>

            <button
              type="button"
              onClick={handleApplyDefaultSettingsToAll}
              className="flex items-center space-x-1 px-3 py-1 bg-rose-500 hover:bg-rose-600 text-white rounded-xl text-xs font-semibold shadow-sm transition-all active:scale-95 cursor-pointer"
              title="Bu versiyon ve ortamı aşağıdaki tüm test case satırlarına uygula"
            >
              <Check className="w-3.5 h-3.5" />
              <span>Tümüne Uygula</span>
            </button>
          </div>
        </div>
      </div>

      {/* Test Cases List / Table View */}
      {filteredCases.length === 0 ? (
        <div className="flex flex-col items-center justify-center p-12 text-center border-2 border-dashed border-slate-200 dark:border-slate-800 rounded-2xl bg-white dark:bg-slate-900/40 text-slate-400 dark:text-slate-500">
          <Layers className="w-10 h-10 mb-3 opacity-30 text-slate-400" />
          <h4 className="text-sm font-semibold text-slate-700 dark:text-slate-300">
            {childSuites.length > 0 ? 'Bu Düzeyde Test Case Bulunmuyor' : 'Test Case Bulunamadı'}
          </h4>
          <p className="text-xs text-slate-500 mt-1 max-w-sm">
            {childSuites.length > 0
              ? 'Bu klasör içerisinde doğrudan tanımlı Test Case yok. Yukarıdaki alt klasörlere girebilir veya yeni case ekleyebilirsiniz.'
              : 'Bu suite içerisinde arama kriterlerinize uygun Test Case bulunmuyor veya henüz Test Case eklenmemiş.'}
          </p>
          <div className="flex items-center space-x-2 mt-4">
            {onAddSubSuite && (
              <button
                type="button"
                onClick={() => onAddSubSuite(suite.id)}
                className="px-3.5 py-1.5 bg-amber-500/10 hover:bg-amber-500/20 text-amber-700 dark:text-amber-300 border border-amber-500/30 text-xs font-semibold rounded-lg shadow-sm transition-all"
              >
                + Alt Klasör Ekle
              </button>
            )}
            <button
              type="button"
              onClick={() => onAddCaseInSuite(suite.id)}
              className="px-3.5 py-1.5 bg-rose-600 hover:bg-rose-500 text-white text-xs font-semibold rounded-lg shadow-sm transition-all"
            >
              + Yeni Test Case Oluştur
            </button>
          </div>
        </div>
      ) : (
        <div className="w-full bg-white dark:bg-slate-900/80 border border-slate-200 dark:border-slate-800 rounded-2xl shadow-sm overflow-hidden">
          <div className="overflow-x-auto w-full">
            <table className="w-full text-left text-xs border-collapse min-w-full">
              <thead className="sticky top-0 z-10 bg-slate-100/90 dark:bg-[#1a2333] border-b border-slate-200 dark:border-slate-700/80 shadow-xs">
                <tr className="text-slate-700 dark:text-slate-200 font-bold uppercase tracking-wider text-[11px]">
                  <th className="py-2.5 px-3 text-center w-10 whitespace-nowrap">#</th>
                  <th className="py-2.5 px-3 w-28 whitespace-nowrap">Test Kodu</th>
                  <th className="py-2.5 px-4 min-w-[200px] whitespace-nowrap">Test Case Başlığı ve Detay</th>
                  <th className="py-2.5 px-3 w-20 text-center whitespace-nowrap">Öncelik</th>
                  <th className="py-2.5 px-3 w-20 text-center whitespace-nowrap">Tip</th>
                  <th className="py-2.5 px-3 w-24 text-center whitespace-nowrap">Son Durum</th>
                  <th className="py-2.5 px-3 w-56 text-center whitespace-nowrap">Koşu Parametreleri</th>
                  <th className="py-2.5 px-4 w-36 text-right whitespace-nowrap">İşlemler</th>
                </tr>
              </thead>
              <tbody className="divide-y divide-slate-100 dark:divide-slate-800/80 text-slate-700 dark:text-slate-200 font-medium">
                {filteredCases.map((tc, index) => {
                  const currentVersion = getCaseVersion(tc.id);
                  const currentEnv = getCaseEnvironment(tc.id);

                  return (
                    <tr
                      key={tc.id}
                      className="hover:bg-slate-50/80 dark:hover:bg-slate-800/40 transition-colors group"
                    >
                      {/* Index */}
                      <td className="py-2.5 px-3 text-center font-mono text-[11px] text-slate-400 whitespace-nowrap">
                        {index + 1}
                      </td>

                      {/* Test Code */}
                      <td className="py-2.5 px-3 whitespace-nowrap">
                        <span className="font-mono text-[11px] font-bold px-2 py-0.5 rounded-lg bg-rose-500/10 text-rose-600 dark:text-rose-400 border border-rose-500/20 inline-flex items-center space-x-1 shrink-0">
                          <FileCode2 className="w-3 h-3" />
                          <span>{tc.code}</span>
                        </span>
                      </td>

                      {/* Title & Details */}
                      <td className="py-2.5 px-4 min-w-0 max-w-xl whitespace-nowrap">
                        <div className="min-w-0">
                          <div
                            onClick={() => onSelectCase(tc)}
                            className="font-bold text-slate-900 dark:text-slate-100 hover:text-rose-600 dark:hover:text-rose-400 cursor-pointer transition-colors text-xs truncate"
                            title={tc.description ? `${tc.title}\n\nAçıklama: ${tc.description}` : tc.title}
                          >
                            {tc.title}
                          </div>

                          <div className="flex items-center space-x-2 pt-0.5 text-[10px] text-slate-400 truncate">
                            {/* Step Count */}
                            <span className="flex items-center space-x-1 shrink-0" title={`${tc.steps?.length || 0} Test Adımı`}>
                              <ListOrdered className="w-3 h-3" />
                              <span>{tc.steps?.length || 0} Adım</span>
                            </span>

                            {/* Description preview */}
                            {tc.description && (
                              <span className="text-slate-400 dark:text-slate-500 truncate" title={tc.description}>
                                &bull; {tc.description}
                              </span>
                            )}

                            {/* Screenshot Indicator */}
                            {tc.screenshotUrl && (
                              <span className="flex items-center space-x-0.5 text-emerald-500 font-semibold shrink-0" title="Görsel Ekli">
                                <ImageIcon className="w-3 h-3" />
                                <span>Görsel</span>
                              </span>
                            )}

                            {/* Jira Story Indicator */}
                            {tc.jiraStoryKey && (
                              <span className="flex items-center space-x-0.5 text-blue-500 font-mono font-semibold shrink-0" title={`Jira: ${tc.jiraStoryKey}`}>
                                <Sparkles className="w-2.5 h-2.5" />
                                <span>{tc.jiraStoryKey}</span>
                              </span>
                            )}
                          </div>
                        </div>
                      </td>

                      {/* Priority */}
                      <td className="py-2.5 px-3 text-center whitespace-nowrap">
                        <span
                          className={`text-[9px] px-2 py-0.5 rounded-full border font-mono font-bold inline-block ${getPriorityBadge(
                            tc.priority
                          )}`}
                        >
                          {tc.priority}
                        </span>
                      </td>

                      {/* Type */}
                      <td className="py-2.5 px-3 text-center whitespace-nowrap">
                        <span
                          className={`text-[9px] px-2 py-0.5 rounded-full border font-mono font-semibold inline-block ${getTypeBadge(
                            tc.type
                          )}`}
                        >
                          {tc.type}
                        </span>
                      </td>

                      {/* Latest Status */}
                      <td className="py-2.5 px-3 text-center whitespace-nowrap">
                        {renderStatusPill(tc)}
                      </td>

                      {/* Run Parameters (Version & Environment) */}
                      <td className="py-2.5 px-3 text-center whitespace-nowrap">
                        <div className="flex items-center justify-center space-x-1.5">
                          {/* Version Input/Select */}
                          <div className="relative">
                            <input
                              type="text"
                              value={currentVersion}
                              onChange={(e) =>
                                setCaseVersions((prev) => ({
                                  ...prev,
                                  [tc.id]: e.target.value,
                                }))
                              }
                              placeholder="v1.0.0"
                              title="Versiyon Numarası"
                              className="w-16 bg-slate-50 dark:bg-slate-950 border border-slate-200 dark:border-slate-700/80 rounded-lg px-2 py-0.5 text-[11px] font-mono font-medium text-slate-800 dark:text-slate-200 focus:outline-none focus:ring-1 focus:ring-rose-500 text-center"
                            />
                          </div>

                          {/* Environment Select */}
                          <div className="relative">
                            <select
                              value={currentEnv}
                              onChange={(e) =>
                                setCaseEnvironments((prev) => ({
                                  ...prev,
                                  [tc.id]: e.target.value,
                                }))
                              }
                              title="Test Ortamı"
                              className="bg-slate-50 dark:bg-slate-950 border border-slate-200 dark:border-slate-700/80 rounded-lg px-2 py-0.5 text-[11px] font-semibold text-slate-800 dark:text-slate-200 focus:outline-none focus:ring-1 focus:ring-rose-500 cursor-pointer"
                            >
                              {PRESET_ENVIRONMENTS.map((env) => (
                                <option key={env} value={env}>
                                  {env}
                                </option>
                              ))}
                            </select>
                          </div>
                        </div>
                      </td>

                      {/* Action Buttons ("İncele" & "Koştur") */}
                      <td className="py-2.5 px-4 text-right whitespace-nowrap">
                        <div className="flex items-center justify-end space-x-1.5">
                          {/* "İncele" Butonu */}
                          <button
                            type="button"
                            onClick={() => onSelectCase(tc)}
                            className="inline-flex items-center space-x-1 px-2 py-1 bg-slate-100 dark:bg-slate-800 hover:bg-slate-200 dark:hover:bg-slate-700 text-slate-700 dark:text-slate-200 rounded-lg text-xs font-semibold border border-slate-200 dark:border-slate-700 shadow-sm transition-all active:scale-95 cursor-pointer"
                            title="Test Case Detaylarını İncele ve Düzenle"
                          >
                            <Eye className="w-3.5 h-3.5 text-rose-500" />
                            <span>İncele</span>
                          </button>

                          {/* "Koştur" Butonu */}
                          {onRunCase && can('EXECUTE_RUN') && (
                            <button
                              type="button"
                              onClick={() => handleRunTestCaseRow(tc)}
                              className="inline-flex items-center space-x-1 px-2.5 py-1 bg-gradient-to-r from-emerald-600 to-teal-600 hover:from-emerald-500 hover:to-teal-500 text-white rounded-lg text-xs font-bold shadow-md shadow-emerald-600/20 transition-all active:scale-95 cursor-pointer"
                              title={`${currentVersion} versiyonu ve ${currentEnv} ortamında test koşusunu başlat`}
                            >
                              <Play className="w-3 h-3 fill-current" />
                              <span>Koştur</span>
                            </button>
                          )}
                        </div>
                      </td>
                    </tr>
                  );
                })}
              </tbody>
            </table>
          </div>
        </div>
      )}

      {/* Excel Import Modal */}
      {projectId && (
        <ExcelImportModal
          isOpen={isImportModalOpen}
          type="TEST_CASES"
          projectId={projectId}
          projectName={projectName || suite.name}
          onClose={() => setIsImportModalOpen(false)}
          onSuccess={async () => {
            if (onCasesChange) {
              await onCasesChange();
            }
          }}
        />
      )}
    </main>
  );
};

export type SidebarTab = 'DASHBOARD' | 'PLANS' | 'EXPLORER' | 'RUNS' | 'DEFECTS' | 'REPORTS' | 'SETTINGS';

interface AppSidebarProps {
  projects?: Project[];
  selectedProject?: Project | null;
  activeTab: SidebarTab;
  onTabChange: (tab: SidebarTab) => void;
  testCasesCount?: number;
  testPlansCount?: number;
  testRunsCount?: number;
  defectsCount?: number;
  onOpenUserManagement?: () => void;
}

export const AppSidebar: React.FC<AppSidebarProps> = ({
  selectedProject,
  activeTab,
  onTabChange,
  testCasesCount = 0,
  testPlansCount = 0,
  testRunsCount = 0,
  defectsCount = 0,
  onOpenUserManagement,
}) => {
  const { isAdmin } = useAuth();
  const [isCollapsed, setIsCollapsed] = useState<boolean>(false);

  // Load collapsed state from localStorage on mount
  useEffect(() => {
    const saved = localStorage.getItem('tcms_sidebar_collapsed');
    if (saved === 'true') {
      setIsCollapsed(true);
    }
  }, []);

  const toggleCollapsed = () => {
    setIsCollapsed((prev) => {
      const next = !prev;
      localStorage.setItem('tcms_sidebar_collapsed', String(next));
      return next;
    });
  };

  // Main Navigation Items Config
  const navItems = [
    {
      id: 'DASHBOARD' as SidebarTab,
      label: 'Ana Sayfa',
      icon: LayoutDashboard,
    },
    {
      id: 'PLANS' as SidebarTab,
      label: 'Test Planları',
      icon: ClipboardList,
      badge: testPlansCount > 0 ? testPlansCount : undefined,
    },
    {
      id: 'EXPLORER' as SidebarTab,
      label: 'Test Senaryoları',
      icon: FileText,
      badge: testCasesCount > 0 ? testCasesCount : undefined,
    },
    {
      id: 'RUNS' as SidebarTab,
      label: 'Test Koşumları',
      icon: Activity,
      badge: testRunsCount > 0 ? testRunsCount : undefined,
    },
    {
      id: 'DEFECTS' as SidebarTab,
      label: 'Defectler & Hatalar',
      icon: Bug,
      badge: defectsCount > 0 ? defectsCount : undefined,
    },
    {
      id: 'REPORTS' as SidebarTab,
      label: 'Test Raporları',
      icon: BarChart3,
    },
    {
      id: 'SETTINGS' as SidebarTab,
      label: 'Sistem Ayarları',
      icon: Settings,
    },
  ];


  // Collapsed Sidebar View
  if (isCollapsed) {
    return (
      <aside className="w-16 border-r border-slate-200 dark:border-slate-800 bg-white dark:bg-[#0c121e] flex flex-col items-center py-3 h-[calc(100vh-4rem)] select-none transition-all duration-300 z-20 shrink-0 justify-between">
        <div className="flex flex-col items-center space-y-3 w-full">
          <button
            type="button"
            onClick={toggleCollapsed}
            className="p-2 rounded-xl bg-slate-100 dark:bg-slate-800/80 hover:bg-[var(--accent-primary)]/10 text-slate-600 dark:text-slate-300 hover:text-[var(--accent-primary)] transition-colors shadow-xs mb-1 cursor-pointer"
            title="Menüyü Genişlet"
          >
            <PanelLeftOpen className="w-4.5 h-4.5" />
          </button>

          {/* Active Project Key Badge */}
          {selectedProject && (
            <div
              onClick={toggleCollapsed}
              className="w-10 h-10 rounded-xl bg-[var(--accent-primary)]/15 text-[var(--accent-primary)] font-mono font-bold text-xs flex items-center justify-center border border-[var(--accent-primary)]/30 mb-1 cursor-pointer shadow-xs"
              title={`Proje: ${selectedProject.name}`}
            >
              {selectedProject.name.charAt(0).toLocaleUpperCase('tr-TR')}
            </div>
          )}

          {/* Nav Icons */}
          <div className="flex flex-col space-y-2 w-full px-2">
            {navItems.map((item) => {
              const Icon = item.icon;
              const isActive = activeTab === item.id;
              return (
                <button
                  key={item.id}
                  type="button"
                  onClick={() => onTabChange(item.id)}
                  className={`w-10 h-10 rounded-xl flex items-center justify-center transition-all cursor-pointer relative group ${
                    isActive
                      ? 'bg-accent-gradient text-white shadow-md shadow-[var(--accent-dark)]/30 scale-105 font-bold'
                      : 'text-slate-600 dark:text-slate-400 hover:bg-slate-100 dark:hover:bg-slate-800/80 hover:text-slate-900 dark:hover:text-slate-100'
                  }`}
                  style={isActive ? { background: 'var(--accent-gradient)' } : undefined}
                  title={item.label}
                >
                  <Icon className="w-4.5 h-4.5" />
                  {item.badge !== undefined && (
                    <span className="absolute top-1 right-1 w-2 h-2 rounded-full bg-[var(--accent-primary)] ring-2 ring-white dark:ring-slate-900" />
                  )}
                </button>
              );
            })}
          </div>
        </div>

        {/* Collapsed Footer: Admin Settings Icon & Expand Toggle */}
        <div className="flex flex-col items-center space-y-2 w-full px-2">
          {isAdmin && (
            <button
              type="button"
              onClick={() => onTabChange('SETTINGS')}
              className={`w-10 h-10 rounded-xl flex items-center justify-center transition-colors cursor-pointer ${
                activeTab === 'SETTINGS'
                  ? 'bg-accent-gradient text-white shadow-sm shadow-[var(--accent-dark)]/30'
                  : 'text-slate-500 hover:text-[var(--accent-primary)] dark:text-slate-400 dark:hover:text-[var(--accent-primary)] hover:bg-slate-100 dark:hover:bg-slate-800'
              }`}
              style={activeTab === 'SETTINGS' ? { background: 'var(--accent-gradient)' } : undefined}
              title="Sistem & Yönetim Ayarları"
              aria-label="Yönetim Ayarları"
            >
              <Settings className="w-4.5 h-4.5" />
            </button>
          )}

          <button
            type="button"
            onClick={toggleCollapsed}
            className="p-2 rounded-xl text-slate-400 hover:text-slate-600 dark:hover:text-slate-200 hover:bg-slate-100 dark:hover:bg-slate-800 transition-colors cursor-pointer"
            title="Menüyü Genişlet"
          >
            <PanelLeftOpen className="w-4 h-4" />
          </button>
        </div>
      </aside>
    );
  }

  // Expanded Sidebar View (240px)
  return (
    <aside className="w-[240px] border-r border-slate-200 dark:border-slate-800 bg-white dark:bg-[#0c121e] flex flex-col h-[calc(100vh-4rem)] select-none transition-all duration-300 z-20 shrink-0 justify-between">
      <div className="flex flex-col flex-1 overflow-hidden">
        {/* 1. Header: Section Title & Collapse Action */}
        <div className="p-2.5 px-3.5 border-b border-slate-200 dark:border-slate-800 bg-slate-50/70 dark:bg-[#141821]/90 flex items-center justify-between shrink-0">
          <span className="text-[10px] font-bold uppercase tracking-wider text-slate-500 dark:text-slate-400">
            Navigasyon Menüsü
          </span>
          <button
            type="button"
            onClick={toggleCollapsed}
            className="p-1 rounded-lg hover:bg-slate-200 dark:hover:bg-slate-800 text-slate-400 hover:text-slate-700 dark:hover:text-slate-200 transition-colors cursor-pointer"
            title="Sol Menüyü Daralt"
          >
            <PanelLeftClose className="w-3.5 h-3.5" />
          </button>
        </div>

        {/* 2. Primary Nav List */}
        <div className="p-2.5 space-y-1 border-b border-slate-200 dark:border-slate-800 shrink-0">
          {navItems.map((item) => {
            const Icon = item.icon;
            const isActive = activeTab === item.id;
            return (
              <button
                key={item.id}
                type="button"
                onClick={() => onTabChange(item.id)}
                className={`w-full flex items-center justify-between px-3 py-2 rounded-xl text-xs font-semibold transition-all duration-150 cursor-pointer ${
                  isActive
                    ? 'bg-accent-gradient text-white shadow-sm shadow-[var(--accent-dark)]/25 font-bold'
                    : 'text-slate-700 dark:text-slate-300 hover:bg-slate-100 dark:hover:bg-slate-800/60 hover:text-slate-900 dark:hover:text-white'
                }`}
                style={isActive ? { background: 'var(--accent-gradient)' } : undefined}
              >
                <div className="flex items-center space-x-2.5">
                  <Icon className={`w-4 h-4 shrink-0 ${isActive ? 'text-white' : 'text-slate-400 group-hover:text-slate-600 dark:group-hover:text-slate-200'}`} />
                  <span className="truncate">{item.label}</span>
                </div>
                {item.badge !== undefined && (
                  <span
                    className={`text-[9px] font-mono px-1.5 py-0.5 rounded-full font-bold ${
                      isActive
                        ? 'bg-white/20 text-white'
                        : 'bg-slate-100 dark:bg-slate-800 text-slate-600 dark:text-slate-300 border border-slate-200 dark:border-slate-700'
                    }`}
                  >
                    {item.badge}
                  </span>
                )}
              </button>
            );
          })}
        </div>

        {/* 3. Project Summary Card */}
        <div className="flex-1 p-3 overflow-y-auto space-y-3">
          <div className="p-3 rounded-xl bg-slate-50 dark:bg-slate-900/50 border border-slate-200 dark:border-slate-800 text-xs space-y-2.5">
            <span className="text-[10px] font-bold uppercase tracking-wider text-slate-500 dark:text-slate-400 block">
              Proje Özeti
            </span>
            <div className="space-y-1.5">
              <div className="flex items-center justify-between text-slate-600 dark:text-slate-300 text-xs py-0.5 border-b border-slate-200/50 dark:border-slate-800/60">
                <span>Test Planları:</span>
                <span className="font-mono font-bold text-slate-900 dark:text-slate-100">{testPlansCount}</span>
              </div>
              <div className="flex items-center justify-between text-slate-600 dark:text-slate-300 text-xs py-0.5 border-b border-slate-200/50 dark:border-slate-800/60">
                <span>Test Senaryoları:</span>
                <span className="font-mono font-bold text-slate-900 dark:text-slate-100">{testCasesCount}</span>
              </div>
              <div className="flex items-center justify-between text-slate-600 dark:text-slate-300 text-xs py-0.5 border-b border-slate-200/50 dark:border-slate-800/60">
                <span>Test Koşumları:</span>
                <span className="font-mono font-bold text-slate-900 dark:text-slate-100">{testRunsCount}</span>
              </div>
              <div className="flex items-center justify-between text-slate-600 dark:text-slate-300 text-xs py-0.5">
                <span>Açık Defectler:</span>
                <span className="font-mono font-bold text-rose-600 dark:text-rose-400">{defectsCount}</span>
              </div>
            </div>
          </div>
        </div>
      </div>

      {/* 4. Footer: Admin Settings Button (Sol Alt Köşe) + Collapse Action */}
      <div className="p-2.5 px-3 border-t border-slate-100 dark:border-slate-800/80 shrink-0 flex items-center justify-between gap-1 bg-slate-50/50 dark:bg-[#141821]/80">
        {/* Admin Settings Button (Bottom Left) */}
        {isAdmin ? (
          <button
            type="button"
            onClick={() => onTabChange('SETTINGS')}
            className={`flex items-center space-x-1.5 px-2 py-1.5 rounded-lg text-xs font-semibold transition-colors cursor-pointer ${
              activeTab === 'SETTINGS'
                ? 'bg-[var(--accent-primary)]/20 text-[var(--accent-primary)]'
                : 'text-slate-700 dark:text-slate-300 hover:text-[var(--accent-primary)] hover:bg-slate-200/70 dark:hover:bg-slate-800'
            }`}
            title="Sistem & Yönetim Ayarları"
            aria-label="Yönetim Ayarları"
          >
            <Settings className="w-3.5 h-3.5 text-[var(--accent-primary)]" />
            <span className="text-[11px]">Ayarlar</span>
          </button>
        ) : (
          <div />
        )}

        {/* Collapse Toggle */}
        <button
          type="button"
          onClick={toggleCollapsed}
          className="flex items-center space-x-1 px-2 py-1.5 rounded-lg text-xs text-slate-400 hover:text-slate-700 dark:hover:text-slate-200 hover:bg-slate-200/70 dark:hover:bg-slate-800 transition-colors cursor-pointer"
          title="Sol Menüyü Daralt"
        >
          <PanelLeftClose className="w-3.5 h-3.5" />
          <span className="text-[11px] hidden sm:inline">Daralt</span>
        </button>
      </div>
    </aside>
  );
};

export const ExplorerTree: React.FC<ExplorerTreeProps> = ({
  tree,
  rootTestCases = [],
  selectedProject,
  selectedCaseId,
  selectedSuiteId,
  onSelectCase,
  onSelectSuite,
  onAddSubSuite,
  onEditSuite,
  onDeleteSuite,
  onAddCaseInSuite,
  onOpenNewSuite,
  onOpenNewCase,
  onEditProject,
  onRunCase,
  onRunSuite,
  onReorderSuite,
}) => {
  const [expandedMap, setExpandedMap] = useState<Record<string, boolean>>({});
  const [searchQuery, setSearchQuery] = useState('');
  const [statusFilter, setStatusFilter] = useState<StatusFilter>('ALL');
  const [draggedSuiteId, setDraggedSuiteId] = useState<string | null>(null);
  const [dragOverSuiteId, setDragOverSuiteId] = useState<string | null>(null);
  const [isRootDragOver, setIsRootDragOver] = useState(false);

  const isSubTreeContainsId = (rootNode: SuiteTreeNode, targetId: string): boolean => {
    if (rootNode.id === targetId) return true;
    if (rootNode.children) {
      for (const child of rootNode.children) {
        if (isSubTreeContainsId(child, targetId)) return true;
      }
    }
    return false;
  };

  const findNodeInTree = (nodes: SuiteTreeNode[], id: string): SuiteTreeNode | null => {
    for (const n of nodes) {
      if (n.id === id) return n;
      if (n.children) {
        const found = findNodeInTree(n.children, id);
        if (found) return found;
      }
    }
    return null;
  };

  const isInvalidDropTarget = (draggedId: string | null, targetId: string): boolean => {
    if (!draggedId) return false;
    if (draggedId === targetId) return true;
    const draggedNode = findNodeInTree(tree, draggedId);
    if (draggedNode) {
      return isSubTreeContainsId(draggedNode, targetId);
    }
    return false;
  };

  const toggleExpand = (suiteId: string, e?: React.MouseEvent) => {
    if (e) e.stopPropagation();
    setExpandedMap((prev) => ({ ...prev, [suiteId]: !prev[suiteId] }));
  };

  const handleExpandAll = () => {
    const map: Record<string, boolean> = {};
    const traverse = (nodes: SuiteTreeNode[]) => {
      nodes.forEach((n) => {
        map[n.id] = true;
        if (n.children) traverse(n.children);
      });
    };
    traverse(tree);
    setExpandedMap(map);
  };

  const handleCollapseAll = () => {
    const map: Record<string, boolean> = {};
    const traverse = (nodes: SuiteTreeNode[]) => {
      nodes.forEach((n) => {
        map[n.id] = false;
        if (n.children) traverse(n.children);
      });
    };
    traverse(tree);
    setExpandedMap(map);
  };

  const getPriorityColor = (priority: string) => {
    switch (priority) {
      case 'BLOCKER':
        return 'bg-red-500/10 dark:bg-red-500/20 text-red-600 dark:text-red-400 border-red-500/30';
      case 'CRITICAL':
        return 'bg-amber-500/10 dark:bg-amber-500/20 text-amber-600 dark:text-amber-400 border-amber-500/30';
      case 'NORMAL':
        return 'bg-blue-500/10 dark:bg-blue-500/20 text-blue-600 dark:text-blue-400 border-blue-500/30';
      case 'LOW':
        return 'bg-slate-500/10 dark:bg-slate-500/20 text-slate-600 dark:text-slate-400 border-slate-500/30';
      default:
        return 'bg-slate-500/10 dark:bg-slate-500/20 text-slate-600 dark:text-slate-400 border-slate-500/30';
    }
  };

  const getTypeBadge = (type: string) => {
    switch (type) {
      case 'WEB':
        return 'text-emerald-500 dark:text-emerald-400';
      case 'MOBILE':
        return 'text-purple-500 dark:text-purple-400';
      case 'API':
        return 'text-cyan-500 dark:text-cyan-400';
      default:
        return 'text-slate-400';
    }
  };

  const getLatestStatusBadge = (testCase: TestCase) => {
    const latestResult = testCase.results && testCase.results.length > 0 ? testCase.results[0] : null;
    const status = latestResult?.status;

    switch (status) {
      case 'PASSED':
        return (
          <span
            className="flex items-center space-x-1 text-[9px] px-1.5 py-0.5 rounded bg-emerald-500/10 dark:bg-emerald-500/20 text-emerald-600 dark:text-emerald-400 border border-emerald-500/30 font-mono font-bold"
            title={`Sonuç: PASSED (${latestResult?.executedAt ? new Date(latestResult.executedAt).toLocaleTimeString() : ''})`}
          >
            <CheckCircle2 className="w-2.5 h-2.5" />
            <span>PASS</span>
          </span>
        );
      case 'FAILED':
        return (
          <span
            className="flex items-center space-x-1 text-[9px] px-1.5 py-0.5 rounded bg-red-500/10 dark:bg-red-500/20 text-red-600 dark:text-red-400 border border-red-500/30 font-mono font-bold"
            title={`Sonuç: FAILED ${latestResult?.errorMessage ? `- ${latestResult.errorMessage}` : ''}`}
          >
            <XCircle className="w-2.5 h-2.5" />
            <span>FAIL</span>
          </span>
        );
      case 'SKIPPED':
        return (
          <span
            className="flex items-center space-x-1 text-[9px] px-1.5 py-0.5 rounded bg-slate-500/10 dark:bg-slate-500/20 text-slate-600 dark:text-slate-400 border border-slate-500/30 font-mono font-bold"
            title="Sonuç: SKIPPED"
          >
            <SkipForward className="w-2.5 h-2.5" />
            <span>SKIP</span>
          </span>
        );
      case 'BLOCKED':
        return (
          <span
            className="flex items-center space-x-1 text-[9px] px-1.5 py-0.5 rounded bg-amber-500/10 dark:bg-amber-500/20 text-amber-700 dark:text-amber-400 border border-amber-500/30 font-mono font-bold"
            title="Sonuç: BLOCKED"
          >
            <Slash className="w-2.5 h-2.5" />
            <span>BLOCK</span>
          </span>
        );
      default:
        return (
          <span
            className="text-[9px] px-1.5 py-0.5 rounded bg-slate-200 dark:bg-slate-800 text-slate-500 dark:text-slate-400 border border-slate-300 dark:border-slate-700/50 font-mono"
            title="Henüz koşturulmadı"
          >
            -
          </span>
        );
    }
  };

  const handleDragStart = (e: React.DragEvent, suiteId: string) => {
    e.stopPropagation();
    setDraggedSuiteId(suiteId);
    e.dataTransfer.setData('text/plain', suiteId);
  };

  const handleDragEnd = () => {
    setDraggedSuiteId(null);
    setDragOverSuiteId(null);
    setIsRootDragOver(false);
  };

  const handleDragOverSuite = (e: React.DragEvent, targetSuiteId: string) => {
    e.preventDefault();
    e.stopPropagation();
    if (draggedSuiteId && !isInvalidDropTarget(draggedSuiteId, targetSuiteId)) {
      setDragOverSuiteId(targetSuiteId);
      setIsRootDragOver(false);
    }
  };

  const handleDropSuite = (e: React.DragEvent, targetSuiteId: string) => {
    e.preventDefault();
    e.stopPropagation();
    setDragOverSuiteId(null);
    if (draggedSuiteId && !isInvalidDropTarget(draggedSuiteId, targetSuiteId) && onReorderSuite) {
      onReorderSuite(draggedSuiteId, targetSuiteId, 0);
      setDraggedSuiteId(null);
    }
  };

  const handleDragOverRoot = (e: React.DragEvent) => {
    e.preventDefault();
    e.stopPropagation();
    if (draggedSuiteId) {
      setIsRootDragOver(true);
      setDragOverSuiteId(null);
    }
  };

  const handleDropRoot = (e: React.DragEvent) => {
    e.preventDefault();
    e.stopPropagation();
    setIsRootDragOver(false);
    if (draggedSuiteId && onReorderSuite) {
      onReorderSuite(draggedSuiteId, null, 0);
      setDraggedSuiteId(null);
    }
  };

  const matchCaseStatus = (tc: TestCase) => {
    if (statusFilter === 'ALL') return true;
    const status = tc.results && tc.results.length > 0 ? tc.results[0].status : 'UNTESTED';
    if (statusFilter === 'UNTESTED') return !tc.results || tc.results.length === 0;
    return status === statusFilter;
  };

  const renderSuiteNode = (node: SuiteTreeNode, depth: number = 0) => {
    const isExpanded = expandedMap[node.id] ?? true;
    const isBeingDragged = draggedSuiteId === node.id;
    const isDragOver = dragOverSuiteId === node.id;
    const isSuiteSelected = selectedSuiteId === node.id;

    // Filter testcases if search query or status filter exists
    const filteredCases = node.testCases.filter((c) => {
      const matchesSearch = searchQuery
        ? c.title.toLowerCase().includes(searchQuery.toLowerCase()) ||
          c.code.toLowerCase().includes(searchQuery.toLowerCase())
        : true;
      const matchesStatus = matchCaseStatus(c);
      return matchesSearch && matchesStatus;
    });

    return (
      <div key={node.id} className="select-none">
        {/* Suite Header Item */}
        <div
          draggable
          onDragStart={(e) => handleDragStart(e, node.id)}
          onDragEnd={handleDragEnd}
          onDragOver={(e) => handleDragOverSuite(e, node.id)}
          onDrop={(e) => handleDropSuite(e, node.id)}
          onDragLeave={() => setDragOverSuiteId(null)}
          style={{ paddingLeft: `${depth * 14 + 12}px` }}
          className={`group flex items-center justify-between py-1.5 pr-2 rounded-lg transition-all cursor-pointer text-xs font-medium ${
            isBeingDragged
              ? 'opacity-40 border border-dashed border-amber-500 bg-amber-500/5'
              : isDragOver
              ? 'bg-blue-600/20 border-2 border-blue-500 text-blue-900 dark:text-blue-200 font-bold shadow-md ring-2 ring-blue-500/30'
              : isSuiteSelected
              ? 'bg-amber-500/15 dark:bg-amber-500/20 text-amber-900 dark:text-amber-200 font-bold border-l-2 border-amber-500 shadow-sm'
              : 'hover:bg-slate-200/60 dark:hover:bg-slate-800/70 text-slate-700 dark:text-slate-300 hover:text-slate-900 dark:hover:text-white'
          }`}
          onClick={(e) => {
            toggleExpand(node.id, e);
            if (onSelectSuite) onSelectSuite(node);
          }}
        >
          <div className="flex items-center space-x-1.5 min-w-0">
            <span className="opacity-0 group-hover:opacity-40 cursor-grab hover:opacity-100 transition-opacity">
              <GripVertical className="w-3 h-3" />
            </span>

            <button
              onClick={(e) => toggleExpand(node.id, e)}
              className="p-0.5 text-slate-400 hover:text-slate-700 dark:hover:text-white rounded"
            >
              {isExpanded ? (
                <ChevronDown className="w-3.5 h-3.5" />
              ) : (
                <ChevronRight className="w-3.5 h-3.5" />
              )}
            </button>

            {isExpanded ? (
              <FolderOpen className="w-4 h-4 text-amber-500 dark:text-amber-400 shrink-0" />
            ) : (
              <Folder className="w-4 h-4 text-amber-500/80 dark:text-amber-400/80 shrink-0" />
            )}

            <span className="truncate font-semibold text-slate-800 dark:text-slate-200">{node.name}</span>
            <span className="text-[10px] text-slate-400 dark:text-slate-500 font-mono ml-1">
              ({node.testCases.length})
            </span>
            {isDragOver && (
              <span className="text-[10px] text-blue-600 dark:text-blue-400 font-bold ml-2 animate-pulse bg-blue-500/10 px-1.5 py-0.5 rounded border border-blue-500/30">
                ↳ Alt Suite yap
              </span>
            )}
          </div>

          {/* Quick Actions for Suite */}
          <div className="opacity-0 group-hover:opacity-100 flex items-center space-x-1 transition-opacity">
            <button
              onClick={(e) => {
                e.stopPropagation();
                onAddCaseInSuite(node.id);
              }}
              title="Test Case Ekle"
              className="p-1 rounded hover:bg-slate-300 dark:hover:bg-slate-700 text-slate-500 dark:text-slate-400 hover:text-blue-600 dark:hover:text-blue-400"
            >
              <Plus className="w-3 h-3" />
            </button>

            {onEditSuite && (
              <button
                onClick={(e) => {
                  e.stopPropagation();
                  onEditSuite(node);
                }}
                title="Suite Düzenle"
                className="p-1 rounded hover:bg-slate-300 dark:hover:bg-slate-700 text-slate-500 dark:text-slate-400 hover:text-amber-500"
              >
                <Pencil className="w-3 h-3" />
              </button>
            )}

            {onDeleteSuite && (
              <button
                onClick={(e) => {
                  e.stopPropagation();
                  if (confirm(`"${node.name}" isimli suite klasörünü silmek istediğinize emin misiniz?`)) {
                    onDeleteSuite(node.id);
                  }
                }}
                title="Suite Sil"
                className="p-1 rounded hover:bg-slate-300 dark:hover:bg-slate-700 text-slate-500 dark:text-slate-400 hover:text-red-500"
              >
                <Trash2 className="w-3 h-3" />
              </button>
            )}
          </div>
        </div>

        {/* Children & Test Cases */}
        {isExpanded && (
          <div className="space-y-0.5">
            {/* Child Suites */}
            {node.children.map((childNode) => renderSuiteNode(childNode, depth + 1))}

            {/* Test Cases inside this suite */}
            {filteredCases.map((tc) => {
              const isSelected = selectedCaseId === tc.id;
              return (
                <div
                  key={tc.id}
                  style={{ paddingLeft: `${(depth + 1) * 14 + 18}px` }}
                  onClick={() => onSelectCase(tc)}
                  className={`group flex items-center justify-between py-1.5 pr-2 rounded-lg transition-all cursor-pointer text-xs ${
                    isSelected
                      ? 'bg-[var(--accent-primary)]/15 dark:bg-[var(--accent-primary)]/25 text-[var(--accent-dark)] dark:text-[var(--accent-primary)] font-bold border-l-2 border-[var(--accent-primary)] shadow-xs'
                      : 'hover:bg-slate-200/50 dark:hover:bg-slate-800/50 text-slate-700 dark:text-slate-300 hover:text-slate-900 dark:hover:text-slate-100'
                  }`}
                >
                  <div className="flex items-center space-x-2 min-w-0 flex-1 mr-2">
                    <FileText className={`w-3.5 h-3.5 shrink-0 ${getTypeBadge(tc.type)}`} />
                    <span className="font-mono text-[10px] text-slate-400 dark:text-slate-500 shrink-0 font-bold">
                      {tc.code}
                    </span>
                    <span className="truncate">{tc.title}</span>
                  </div>

                  <div className="flex items-center space-x-1.5 shrink-0">
                    {/* Latest Status Badge */}
                    {getLatestStatusBadge(tc)}

                    {/* Run Command Button */}
                    {onRunCase && (
                      <button
                        onClick={(e) => {
                          e.stopPropagation();
                          onRunCase(tc);
                        }}
                        title="Test Case'i Koştur (Run)"
                        className="p-1 rounded bg-emerald-500/10 hover:bg-emerald-500/20 text-emerald-600 dark:text-emerald-400 border border-emerald-500/30 flex items-center space-x-1 transition-all opacity-0 group-hover:opacity-100 font-semibold text-[10px]"
                      >
                        <Play className="w-3 h-3 fill-current text-emerald-500" />
                        <span>Run</span>
                      </button>
                    )}

                    <span
                      className={`text-[9px] px-1.5 py-0.5 rounded border font-mono font-bold ${getPriorityColor(
                        tc.priority
                      )}`}
                    >
                      {tc.priority}
                    </span>
                  </div>
                </div>
              );
            })}
          </div>
        )}
      </div>
    );
  };

  return (
    <aside className="w-80 border-r border-slate-200 dark:border-slate-800 bg-white dark:bg-slate-900/50 flex flex-col h-[calc(100vh-4rem)] select-none transition-colors duration-200">
      {/* Active Test Project Info & Actions */}
      {selectedProject && (
        <div className="p-3.5 bg-slate-50/80 dark:bg-slate-900/80 border-b border-slate-200 dark:border-slate-800 space-y-2.5">
          <div className="flex items-center justify-between">
            <div className="flex items-center space-x-2 min-w-0">
              <span className="font-mono text-[10px] font-bold px-2 py-0.5 rounded bg-rose-500/10 text-rose-600 dark:text-rose-400 border border-rose-500/20 shrink-0">
                [{selectedProject.key}]
              </span>
              <h2 className="text-xs font-bold text-slate-800 dark:text-slate-100 truncate" title={selectedProject.name}>
                {selectedProject.name}
              </h2>
            </div>
            <div className="flex items-center space-x-1.5 shrink-0">
              <span className="text-[10px] text-slate-400 font-mono">Test Projesi</span>
              {onEditProject && (
                <button
                  onClick={() => onEditProject(selectedProject)}
                  className="p-1 rounded-md text-slate-400 hover:text-rose-500 hover:bg-rose-500/10 transition-colors"
                  title="Test Projesini Düzenle / Sil"
                >
                  <Pencil className="w-3 h-3" />
                </button>
              )}
            </div>
          </div>

          {/* Project-level Buttons: Yeni Suite & Yeni Case */}
          <div className="grid grid-cols-2 gap-2 pt-1">
            <button
              onClick={() => onOpenNewSuite ? onOpenNewSuite() : onAddSubSuite('')}
              className="flex items-center justify-center space-x-1.5 px-2.5 py-1.5 text-xs font-semibold bg-amber-500/10 hover:bg-amber-500/20 text-amber-700 dark:text-amber-300 border border-amber-500/30 rounded-lg transition-all shadow-sm active:scale-95 cursor-pointer"
              title="Proje Altında Yeni Suite Oluştur"
            >
              <FolderPlus className="w-3.5 h-3.5 text-amber-500 shrink-0" />
              <span>+ Yeni Suite</span>
            </button>

            <button
              onClick={() => onOpenNewCase ? onOpenNewCase() : onAddCaseInSuite('')}
              className="flex items-center justify-center space-x-1.5 px-2.5 py-1.5 text-xs font-semibold bg-[var(--accent-primary)]/10 hover:bg-[var(--accent-primary)]/20 text-[var(--accent-primary)] border border-[var(--accent-primary)]/30 rounded-lg transition-all shadow-sm active:scale-95 cursor-pointer"
              title="Proje Altında Yeni Case Oluştur"
            >
              <FilePlus className="w-3.5 h-3.5 text-[var(--accent-primary)] shrink-0" />
              <span>+ Yeni Case</span>
            </button>
          </div>
        </div>
      )}

      {/* Explorer Tree Toolbar & Search */}
      <div className="p-3.5 border-b border-slate-200 dark:border-slate-800 space-y-2.5">
        <div className="flex items-center justify-between">
          <div className="flex items-center space-x-2">
            <Layers className="w-4 h-4 text-blue-500" />
            <h2 className="text-xs font-bold uppercase tracking-wider text-slate-700 dark:text-slate-300">Explorer</h2>
          </div>
          <div className="flex items-center space-x-1">
            <button
              onClick={handleExpandAll}
              className="p-1 rounded hover:bg-slate-100 dark:hover:bg-slate-800 text-slate-400 hover:text-slate-700 dark:hover:text-slate-200 transition-colors"
              title="Tümünü Genişlet (Expand All)"
            >
              <Maximize2 className="w-3 h-3" />
            </button>
            <button
              onClick={handleCollapseAll}
              className="p-1 rounded hover:bg-slate-100 dark:hover:bg-slate-800 text-slate-400 hover:text-slate-700 dark:hover:text-slate-200 transition-colors"
              title="Tümünü Daralt (Collapse All)"
            >
              <Minimize2 className="w-3 h-3" />
            </button>
          </div>
        </div>

        {/* Search Input */}
        <div className="relative">
          <Search className="w-3.5 h-3.5 text-slate-400 absolute left-2.5 top-1/2 -translate-y-1/2" />
          <input
            type="text"
            placeholder="Case ya da Kod ara..."
            value={searchQuery}
            onChange={(e) => setSearchQuery(e.target.value)}
            className="w-full bg-slate-100 dark:bg-slate-900/80 border border-slate-200 dark:border-slate-800 rounded-lg text-xs text-slate-800 dark:text-slate-200 placeholder-slate-400 dark:placeholder-slate-500 pl-8 pr-3 py-1.5 focus:outline-none focus:ring-1 focus:ring-blue-500 transition-colors"
          />
        </div>

        {/* Status Filter Chips */}
        <div className="flex items-center space-x-1 overflow-x-auto pb-0.5 text-[10px] font-medium">
          <button
            onClick={() => setStatusFilter('ALL')}
            className={`px-2 py-0.5 rounded-full border transition-colors ${
              statusFilter === 'ALL'
                ? 'bg-accent-gradient text-white border-[var(--accent-dark)] font-bold'
                : 'bg-slate-100 dark:bg-slate-800 text-slate-600 dark:text-slate-400 border-slate-200 dark:border-slate-700'
            }`}
            style={statusFilter === 'ALL' ? { background: 'var(--accent-gradient)' } : undefined}
          >
            Tümü
          </button>
          <button
            onClick={() => setStatusFilter('PASSED')}
            className={`px-2 py-0.5 rounded-full border transition-colors ${
              statusFilter === 'PASSED'
                ? 'bg-emerald-600 text-white border-emerald-600'
                : 'bg-emerald-500/10 text-emerald-600 dark:text-emerald-400 border-emerald-500/30'
            }`}
          >
            Pass
          </button>
          <button
            onClick={() => setStatusFilter('FAILED')}
            className={`px-2 py-0.5 rounded-full border transition-colors ${
              statusFilter === 'FAILED'
                ? 'bg-red-600 text-white border-red-600'
                : 'bg-red-500/10 text-red-600 dark:text-red-400 border-red-500/30'
            }`}
          >
            Fail
          </button>
          <button
            onClick={() => setStatusFilter('BLOCKED')}
            className={`px-2 py-0.5 rounded-full border transition-colors ${
              statusFilter === 'BLOCKED'
                ? 'bg-amber-600 text-white border-amber-600'
                : 'bg-amber-500/10 text-amber-700 dark:text-amber-400 border-amber-500/30'
            }`}
          >
            Block
          </button>
          <button
            onClick={() => setStatusFilter('UNTESTED')}
            className={`px-2 py-0.5 rounded-full border transition-colors ${
              statusFilter === 'UNTESTED'
                ? 'bg-slate-600 text-white border-slate-600'
                : 'bg-slate-200 dark:bg-slate-800 text-slate-500 border-slate-300 dark:border-slate-700'
            }`}
          >
            Koşulmadı
          </button>
        </div>
      </div>

      {/* Root Level Drop Zone Banner when Dragging */}
      {draggedSuiteId && (
        <div
          onDragOver={handleDragOverRoot}
          onDragLeave={() => setIsRootDragOver(false)}
          onDrop={handleDropRoot}
          className={`mx-3 my-2 p-2.5 border-2 border-dashed rounded-xl flex items-center justify-center space-x-2 transition-all cursor-pointer text-xs font-bold ${
            isRootDragOver
              ? 'border-blue-500 bg-blue-500/25 text-blue-700 dark:text-blue-200 scale-[1.02] shadow-md ring-2 ring-blue-500/40'
              : 'border-amber-500/50 bg-amber-500/10 text-amber-800 dark:text-amber-300 hover:border-amber-500 hover:bg-amber-500/20'
          }`}
        >
          <FolderPlus className={`w-4 h-4 text-amber-500 ${isRootDragOver ? 'animate-bounce text-blue-500' : ''}`} />
          <span>📁 Ana Dizine (Kök Seviyeye) Taşı</span>
        </div>
      )}

      {/* Tree View Scrollable Content */}
      <div
        onDragOver={(e) => {
          if (draggedSuiteId) handleDragOverRoot(e);
        }}
        onDrop={(e) => {
          if (draggedSuiteId) handleDropRoot(e);
        }}
        className={`flex-1 overflow-y-auto p-2 space-y-1 transition-all ${
          isRootDragOver ? 'bg-blue-500/5 ring-2 ring-blue-500/20 rounded-lg' : ''
        }`}
      >
        {(() => {
          const filteredRootCases = (rootTestCases || []).filter((c) => {
            const matchesSearch = searchQuery
              ? c.title.toLowerCase().includes(searchQuery.toLowerCase()) ||
                c.code.toLowerCase().includes(searchQuery.toLowerCase())
              : true;
            const matchesStatus = matchCaseStatus(c);
            return matchesSearch && matchesStatus;
          });

          return (
            <>
              {filteredRootCases.length > 0 && (
                <div className="mb-2 space-y-0.5 pb-2 border-b border-slate-200 dark:border-slate-800">
                  <div
                    onClick={() => {
                      if (onSelectSuite) {
                        onSelectSuite({
                          id: '__root_cases__',
                          name: "Kök Test Case'leri (Suite'siz)",
                          orderIndex: 0,
                          parentId: null,
                          children: [],
                          testCases: rootTestCases,
                        });
                      }
                    }}
                    className="px-2 py-1 flex items-center justify-between text-[11px] font-bold text-slate-600 dark:text-slate-400 uppercase tracking-wider cursor-pointer hover:text-blue-600 transition-colors"
                  >
                    <div className="flex items-center space-x-1.5">
                      <FileText className="w-3.5 h-3.5 text-blue-500" />
                      <span>Kök Test Case'leri ({filteredRootCases.length})</span>
                    </div>
                    <span className="text-[9px] font-mono text-slate-400 font-normal">Tümünü Gör →</span>
                  </div>
                  {filteredRootCases.map((tc) => {
                    const isSelected = selectedCaseId === tc.id;
                    return (
                      <div
                        key={tc.id}
                        onClick={() => onSelectCase(tc)}
                        className={`group flex items-center justify-between py-1.5 px-2 rounded-lg transition-all cursor-pointer text-xs ${
                          isSelected
                            ? 'bg-[var(--accent-primary)]/15 dark:bg-[var(--accent-primary)]/25 text-[var(--accent-dark)] dark:text-[var(--accent-primary)] font-bold border-l-2 border-[var(--accent-primary)] shadow-xs'
                            : 'hover:bg-slate-200/50 dark:hover:bg-slate-800/50 text-slate-700 dark:text-slate-300 hover:text-slate-900 dark:hover:text-slate-100'
                        }`}
                      >
                        <div className="flex items-center space-x-2 min-w-0 flex-1 mr-2">
                          <FileText className={`w-3.5 h-3.5 shrink-0 ${getTypeBadge(tc.type)}`} />
                          <span className="font-mono text-[10px] text-slate-400 dark:text-slate-500 shrink-0 font-bold">
                            {tc.code}
                          </span>
                          <span className="truncate">{tc.title}</span>
                        </div>

                        <div className="flex items-center space-x-1.5 shrink-0">
                          {getLatestStatusBadge(tc)}
                          {onRunCase && (
                            <button
                              onClick={(e) => {
                                e.stopPropagation();
                                onRunCase(tc);
                              }}
                              title="Test Case'i Koştur (Run)"
                              className="p-1 rounded bg-emerald-500/10 hover:bg-emerald-500/20 text-emerald-600 dark:text-emerald-400 border border-emerald-500/30 flex items-center space-x-1 transition-all opacity-0 group-hover:opacity-100 font-semibold text-[10px]"
                            >
                              <Play className="w-3 h-3 fill-current text-emerald-500" />
                              <span>Run</span>
                            </button>
                          )}
                          <span
                            className={`text-[9px] px-1.5 py-0.5 rounded border font-mono font-bold ${getPriorityColor(
                              tc.priority
                            )}`}
                          >
                            {tc.priority}
                          </span>
                        </div>
                      </div>
                    );
                  })}
                </div>
              )}

              {tree.length === 0 && filteredRootCases.length === 0 ? (
                <div className="text-center py-10 px-4 text-slate-400 dark:text-slate-500 text-xs">
                  <Folder className="w-8 h-8 mx-auto mb-2 opacity-30 text-slate-400" />
                  <p>Henüz klasör (Suite) veya Test Case bulunmuyor.</p>
                  <p className="text-[10px] mt-1 text-slate-500">Yukarıdaki butonlardan yeni Suite veya Case ekleyebilirsiniz.</p>
                </div>
              ) : (
                tree.map((node) => renderSuiteNode(node, 0))
              )}
            </>
          );
        })()}
      </div>
    </aside>
  );
};

export const NewCaseModal: React.FC<NewCaseModalProps> = ({
  isOpen,
  onClose,
  projectId,
  projectName,
  defaultSuiteId,
  suites = [],
  onSubmit,
  onRefreshSuites,
}) => {
  const [title, setTitle] = useState('');
  const [selectedSuiteId, setSelectedSuiteId] = useState<string>('');
  const [description, setDescription] = useState('');
  const [preconditions, setPreconditions] = useState('');
  const [errorMsg, setErrorMsg] = useState('');
  const [isSubmitting, setIsSubmitting] = useState(false);

  // Module Management State
  const [localSuites, setLocalSuites] = useState<SuiteTreeNode[]>(suites);
  const [isAddingNewModule, setIsAddingNewModule] = useState(false);
  const [newModuleName, setNewModuleName] = useState('');
  const [isCreatingModule, setIsCreatingModule] = useState(false);
  const [isManagingModules, setIsManagingModules] = useState(false);

  // Module Edit State
  const [editingModuleId, setEditingModuleId] = useState<string | null>(null);
  const [editingModuleName, setEditingModuleName] = useState('');
  const [isUpdatingModule, setIsUpdatingModule] = useState(false);

  // Sync suites from prop
  useEffect(() => {
    setLocalSuites(suites);
  }, [suites]);

  // Flatten suites for dropdown display
  const flattenedSuites = useMemo(() => {
    const flatten = (nodes: SuiteTreeNode[], depth = 0): { id: string; name: string; depth: number }[] => {
      let list: { id: string; name: string; depth: number }[] = [];
      nodes.forEach((n) => {
        list.push({ id: n.id, name: n.name, depth });
        if (n.children && n.children.length > 0) {
          list = list.concat(flatten(n.children, depth + 1));
        }
      });
      return list;
    };
    return flatten(localSuites);
  }, [localSuites]);

  useEffect(() => {
    if (isOpen) {
      setTitle('');
      setSelectedSuiteId(defaultSuiteId || '');
      setDescription('');
      setPreconditions('');
      setErrorMsg('');
      setIsAddingNewModule(false);
      setIsManagingModules(false);
      setNewModuleName('');
    }
  }, [isOpen, defaultSuiteId]);

  if (!isOpen) return null;

  // Handle create new module inline
  const handleCreateModule = async (e?: React.FormEvent) => {
    if (e) e.preventDefault();
    if (!newModuleName.trim() || !projectId) return;

    setIsCreatingModule(true);
    setErrorMsg('');
    try {
      const created = await SuitesService.create({
        name: newModuleName.trim(),
        projectId,
      });

      // Update local suites list
      const updatedList = [...localSuites, { ...created, children: [] }];
      setLocalSuites(updatedList);
      setSelectedSuiteId(created.id);
      setNewModuleName('');
      setIsAddingNewModule(false);

      if (onRefreshSuites) {
        onRefreshSuites();
      }
    } catch (err: any) {
      console.error(err);
      setErrorMsg('Yeni modül oluşturulurken bir hata meydana geldi.');
    } finally {
      setIsCreatingModule(false);
    }
  };

  // Handle delete module
  const handleDeleteModule = async (moduleId: string, moduleName: string) => {
    if (!confirm(`'${moduleName}' modülünü silmek istediğinize emin misiniz?`)) return;

    try {
      await SuitesService.delete(moduleId);
      setLocalSuites((prev) => prev.filter((s) => s.id !== moduleId));
      if (selectedSuiteId === moduleId) {
        setSelectedSuiteId('');
      }
      if (onRefreshSuites) {
        onRefreshSuites();
      }
    } catch (err: any) {
      console.error(err);
      setErrorMsg('Modül silinirken bir hata meydana geldi.');
    }
  };

  // Handle start editing module
  const handleStartEditModule = (mod: { id: string; name: string }) => {
    setEditingModuleId(mod.id);
    setEditingModuleName(mod.name);
  };

  // Handle save module rename
  const handleSaveEditModule = async (moduleId: string) => {
    if (!editingModuleName.trim()) return;

    setIsUpdatingModule(true);
    try {
      await SuitesService.update(moduleId, { name: editingModuleName.trim() });
      setLocalSuites((prev) =>
        prev.map((s) => (s.id === moduleId ? { ...s, name: editingModuleName.trim() } : s))
      );
      setEditingModuleId(null);
      if (onRefreshSuites) {
        onRefreshSuites();
      }
    } catch (err: any) {
      console.error(err);
      setErrorMsg('Modül adı güncellenirken bir hata oluştu.');
    } finally {
      setIsUpdatingModule(false);
    }
  };

  const handleSubmit = async (e: React.FormEvent) => {
    e.preventDefault();
    if (!title.trim()) return;

    setIsSubmitting(true);
    setErrorMsg('');
    try {
      await onSubmit({
        title: title.trim(),
        projectId,
        suiteId: selectedSuiteId ? selectedSuiteId : undefined,
        description: description.trim() || undefined,
        precondition: preconditions.trim() || undefined,
        steps: [],
      });
      onClose();
    } catch (err: any) {
      console.error(err);
      const message =
        err?.response?.data?.message || err?.message || 'Test Senaryosu oluşturulurken bir hata meydana geldi.';
      setErrorMsg(Array.isArray(message) ? message.join(', ') : message);
    } finally {
      setIsSubmitting(false);
    }
  };

  return (
    <div className="fixed inset-0 z-50 bg-black/60 backdrop-blur-xs flex items-center justify-center p-4">
      <div className="bg-white dark:bg-[#161f30] border border-slate-200 dark:border-slate-700 rounded-2xl w-full max-w-lg shadow-2xl overflow-hidden animate-scaleUp text-slate-800 dark:text-slate-100 flex flex-col max-h-[90vh]">
        {/* Header */}
        <div className="px-6 py-4 border-b border-slate-100 dark:border-slate-800 flex items-center justify-between bg-slate-50/70 dark:bg-slate-900/50 shrink-0">
          <div className="flex items-center space-x-2.5">
            <div className="p-2 rounded-xl bg-blue-500/10 text-blue-600 dark:text-blue-400">
              <FileText className="w-4 h-4" />
            </div>
            <div>
              <h3 className="text-sm font-bold text-slate-900 dark:text-slate-100">
                Yeni Test Senaryosu Oluştur
              </h3>
              {projectName && (
                <p className="text-[11px] text-slate-400 font-medium">Proje: {projectName}</p>
              )}
            </div>
          </div>
          <button
            type="button"
            onClick={onClose}
            className="text-slate-400 hover:text-slate-700 dark:hover:text-white p-1 rounded-lg transition-colors cursor-pointer"
          >
            <X className="w-4 h-4" />
          </button>
        </div>

        {errorMsg && (
          <div className="mx-6 mt-4 p-3 bg-red-500/10 border border-red-500/30 rounded-xl text-xs text-red-600 dark:text-red-400 font-medium shrink-0">
            {errorMsg}
          </div>
        )}

        <form onSubmit={handleSubmit} className="p-6 space-y-4 text-xs overflow-y-auto flex-1">
          {/* Scenario Title */}
          <div className="space-y-1.5">
            <label className="font-bold text-slate-700 dark:text-slate-300">
              Senaryo Başlığı *
            </label>
            <input
              type="text"
              required
              placeholder="Örn: Kullanıcı Girişi ve İki Faktörlü Doğrulama Akışı"
              value={title}
              onChange={(e) => setTitle(e.target.value)}
              className="w-full bg-slate-50 dark:bg-slate-800 border border-slate-200 dark:border-slate-700 rounded-xl px-3.5 py-2 text-xs text-slate-900 dark:text-slate-100 placeholder-slate-400 focus:outline-none focus:ring-2 focus:ring-blue-500/30 shadow-xs font-medium"
            />
          </div>

          {/* Module Management & Selection */}
          <div className="space-y-2 p-3 bg-slate-50/70 dark:bg-slate-900/40 rounded-xl border border-slate-200/70 dark:border-slate-800">
            <div className="flex items-center justify-between">
              <label className="font-bold text-slate-700 dark:text-slate-300 flex items-center space-x-1.5">
                <Folder className="w-3.5 h-3.5 text-amber-500" />
                <span>Modül</span>
              </label>

              <div className="flex items-center space-x-2">
                {!isAddingNewModule && (
                  <button
                    type="button"
                    onClick={() => {
                      setIsAddingNewModule(true);
                      setIsManagingModules(false);
                    }}
                    className="inline-flex items-center space-x-1 text-[11px] font-bold text-blue-600 dark:text-blue-400 hover:text-blue-700 dark:hover:text-blue-300 cursor-pointer"
                  >
                    <Plus className="w-3 h-3" />
                    <span>+ Yeni Modül Ekle</span>
                  </button>
                )}

                <button
                  type="button"
                  onClick={() => {
                    setIsManagingModules(!isManagingModules);
                    setIsAddingNewModule(false);
                  }}
                  className="inline-flex items-center space-x-1 text-[11px] font-semibold text-slate-500 hover:text-slate-800 dark:hover:text-slate-200 cursor-pointer"
                >
                  <SlidersHorizontal className="w-3 h-3" />
                  <span>{isManagingModules ? 'Kapat' : 'Yönet'}</span>
                </button>
              </div>
            </div>

            {/* Inline Add New Module Form */}
            {isAddingNewModule && (
              <div className="p-2.5 bg-blue-50/60 dark:bg-blue-950/30 border border-blue-200/80 dark:border-blue-800/60 rounded-xl space-y-2 animate-in fade-in duration-150">
                <span className="text-[11px] font-bold text-blue-700 dark:text-blue-300 block">
                  Yeni Modül Tanımla
                </span>
                <div className="flex items-center gap-1.5">
                  <input
                    type="text"
                    placeholder="Örn: Ödeme & Kart İşlemleri, Kullanıcı Ayarları..."
                    value={newModuleName}
                    onChange={(e) => setNewModuleName(e.target.value)}
                    onKeyDown={(e) => {
                      if (e.key === 'Enter') {
                        e.preventDefault();
                        handleCreateModule();
                      }
                    }}
                    className="flex-1 bg-white dark:bg-[#161f30] border border-blue-300 dark:border-blue-700 rounded-lg px-2.5 py-1.5 text-xs text-slate-900 dark:text-slate-100 placeholder-slate-400 focus:outline-none focus:ring-1 focus:ring-blue-500 font-medium"
                    autoFocus
                  />
                  <button
                    type="button"
                    disabled={isCreatingModule || !newModuleName.trim()}
                    onClick={() => handleCreateModule()}
                    className="px-3 py-1.5 bg-blue-600 hover:bg-blue-700 disabled:opacity-50 text-white rounded-lg font-bold text-xs shadow-xs cursor-pointer inline-flex items-center space-x-1"
                  >
                    {isCreatingModule ? (
                      <Sparkles className="w-3.5 h-3.5 animate-spin" />
                    ) : (
                      <Plus className="w-3.5 h-3.5" />
                    )}
                    <span>Ekle</span>
                  </button>
                  <button
                    type="button"
                    onClick={() => {
                      setIsAddingNewModule(false);
                      setNewModuleName('');
                    }}
                    className="p-1.5 text-slate-400 hover:text-slate-600 dark:hover:text-slate-200 rounded-lg cursor-pointer"
                    title="İptal"
                  >
                    <X className="w-3.5 h-3.5" />
                  </button>
                </div>
              </div>
            )}

            {/* Manage Modules List Panel */}
            {isManagingModules && (
              <div className="p-2.5 bg-white dark:bg-slate-800/80 border border-slate-200 dark:border-slate-700 rounded-xl space-y-2 animate-in fade-in duration-150">
                <div className="flex items-center justify-between pb-1 border-b border-slate-100 dark:border-slate-700 text-[11px] font-bold text-slate-600 dark:text-slate-300">
                  <span>Mevcut Modüller ({flattenedSuites.length})</span>
                  <span className="text-[10px] text-slate-400 font-normal">Düzenle / Sil</span>
                </div>

                <div className="max-h-36 overflow-y-auto space-y-1.5 pr-1">
                  {flattenedSuites.length === 0 ? (
                    <p className="text-[11px] text-slate-400 py-2 text-center">
                      Henüz tanımlı modül bulunmuyor.
                    </p>
                  ) : (
                    flattenedSuites.map((mod) => (
                      <div
                        key={mod.id}
                        className="flex items-center justify-between p-1.5 px-2 rounded-lg bg-slate-50 dark:bg-slate-900/60 border border-slate-100 dark:border-slate-800 text-xs"
                      >
                        {editingModuleId === mod.id ? (
                          <div className="flex items-center gap-1.5 flex-1 pr-1">
                            <input
                              type="text"
                              value={editingModuleName}
                              onChange={(e) => setEditingModuleName(e.target.value)}
                              className="flex-1 bg-white dark:bg-[#161f30] border border-blue-400 rounded px-2 py-0.5 text-xs text-slate-900 dark:text-slate-100"
                              autoFocus
                            />
                            <button
                              type="button"
                              disabled={isUpdatingModule}
                              onClick={() => handleSaveEditModule(mod.id)}
                              className="p-1 bg-emerald-600 text-white rounded hover:bg-emerald-700"
                              title="Kaydet"
                            >
                              <Check className="w-3 h-3" />
                            </button>
                            <button
                              type="button"
                              onClick={() => setEditingModuleId(null)}
                              className="p-1 text-slate-400 hover:text-slate-600"
                              title="Vazgeç"
                            >
                              <X className="w-3 h-3" />
                            </button>
                          </div>
                        ) : (
                          <>
                            <span className="font-medium text-slate-800 dark:text-slate-200 truncate flex-1">
                              📁 {mod.name}
                            </span>
                            <div className="flex items-center space-x-1 shrink-0">
                              <button
                                type="button"
                                onClick={() => handleStartEditModule(mod)}
                                className="p-1 text-slate-400 hover:text-blue-600 rounded"
                                title="Yeniden Adlandır"
                              >
                                <Pencil className="w-3 h-3" />
                              </button>
                              <button
                                type="button"
                                onClick={() => handleDeleteModule(mod.id, mod.name)}
                                className="p-1 text-slate-400 hover:text-rose-600 rounded"
                                title="Modülü Sil"
                              >
                                <Trash2 className="w-3 h-3" />
                              </button>
                            </div>
                          </>
                        )}
                      </div>
                    ))
                  )}
                </div>
              </div>
            )}

            {/* Module Selector Dropdown */}
            <select
              value={selectedSuiteId}
              onChange={(e) => setSelectedSuiteId(e.target.value)}
              className="w-full bg-white dark:bg-slate-800 border border-slate-200 dark:border-slate-700 rounded-xl px-3 py-2 text-xs text-slate-800 dark:text-slate-200 focus:outline-none focus:ring-2 focus:ring-blue-500/30 font-medium cursor-pointer shadow-xs"
            >
              <option value="">📁 Ana Modül (Modülsüz / Proje Geneli)</option>
              {flattenedSuites.map((s) => (
                <option key={s.id} value={s.id}>
                  {'\u00A0'.repeat(s.depth * 3)}↳ 📁 {s.name}
                </option>
              ))}
            </select>
          </div>

          {/* Preconditions */}
          <div className="space-y-1.5">
            <label className="font-bold text-slate-700 dark:text-slate-300">
              Önkoşullar (Opsiyonel)
            </label>
            <input
              type="text"
              placeholder="Örn: Kullanıcı oturum açmış olmalı, bakiye > 100 TL olmalı"
              value={preconditions}
              onChange={(e) => setPreconditions(e.target.value)}
              className="w-full bg-slate-50 dark:bg-slate-800 border border-slate-200 dark:border-slate-700 rounded-xl px-3.5 py-2 text-xs text-slate-900 dark:text-slate-100 placeholder-slate-400 focus:outline-none focus:ring-2 focus:ring-blue-500/30 shadow-xs"
            />
          </div>

          {/* Description */}
          <div className="space-y-1.5">
            <label className="font-bold text-slate-700 dark:text-slate-300">
              Açıklama (Opsiyonel)
            </label>
            <textarea
              rows={3}
              placeholder="Senaryonun amacı, test adımları ve beklenen genel davranış..."
              value={description}
              onChange={(e) => setDescription(e.target.value)}
              className="w-full bg-slate-50 dark:bg-slate-800 border border-slate-200 dark:border-slate-700 rounded-xl px-3.5 py-2 text-xs text-slate-900 dark:text-slate-100 placeholder-slate-400 focus:outline-none focus:ring-2 focus:ring-blue-500/30 shadow-xs"
            />
          </div>

          {/* Actions */}
          <div className="flex items-center justify-end space-x-2 pt-3 border-t border-slate-100 dark:border-slate-800">
            <button
              type="button"
              onClick={onClose}
              className="px-4 py-2 rounded-xl text-xs font-semibold text-slate-600 dark:text-slate-400 hover:bg-slate-100 dark:hover:bg-slate-800 transition-colors cursor-pointer"
            >
              İptal
            </button>
            <button
              type="submit"
              disabled={isSubmitting || !title.trim()}
              className="inline-flex items-center space-x-1.5 px-4 py-2 rounded-xl text-xs font-bold text-white bg-accent-gradient hover:brightness-110 disabled:opacity-50 transition-all shadow-md shadow-[var(--accent-dark)]/20 cursor-pointer"
            >
              <Plus className="w-3.5 h-3.5" />
              <span>{isSubmitting ? 'Oluşturuluyor...' : 'Senaryoyu Oluştur'}</span>
            </button>
          </div>
        </form>
      </div>
    </div>
  );
};

export const Header: React.FC<HeaderProps> = ({
  projects = [],
  selectedProject = null,
  testCases = [],
  testPlans = [],
  testRuns = [],
  defects = [],
  activeTab = 'DASHBOARD',
  selectedSuite = null,
  selectedCase = null,
  selectedPlan = null,
  selectedRun = null,
  onSelectProject,
  onOpenNewProject,
  onEditProject,
  onDeleteProject,
  onNavigateHome,
  onSelectCase,
  onSelectPlan,
  onSelectRun,
  onSelectDefect,
  onTabChange,
}) => {
  const { currentUser, role, isViewer, can, logout } = useAuth();
  const [isUserDropdownOpen, setIsUserDropdownOpen] = useState(false);
  const [isProjectDropdownOpen, setIsProjectDropdownOpen] = useState(false);
  const [projectSearchQuery, setProjectSearchQuery] = useState('');

  // Global Top Navigation Search State
  const [globalSearchQuery, setGlobalSearchQuery] = useState('');
  const [isSearchFocused, setIsSearchFocused] = useState(false);

  const userDropdownRef = useRef<HTMLDivElement>(null);
  const projectDropdownRef = useRef<HTMLDivElement>(null);
  const projectSearchInputRef = useRef<HTMLInputElement>(null);
  const globalSearchInputRef = useRef<HTMLInputElement>(null);
  const searchContainerRef = useRef<HTMLDivElement>(null);

  // Close dropdowns on click outside or Escape key
  useEffect(() => {
    const handleClickOutside = (event: MouseEvent) => {
      if (userDropdownRef.current && !userDropdownRef.current.contains(event.target as Node)) {
        setIsUserDropdownOpen(false);
      }
      if (projectDropdownRef.current && !projectDropdownRef.current.contains(event.target as Node)) {
        setIsProjectDropdownOpen(false);
      }
      if (searchContainerRef.current && !searchContainerRef.current.contains(event.target as Node)) {
        setIsSearchFocused(false);
      }
    };

    const handleKeyDown = (e: KeyboardEvent) => {
      if ((e.metaKey || e.ctrlKey) && e.key === 'k') {
        e.preventDefault();
        globalSearchInputRef.current?.focus();
        setIsSearchFocused(true);
      }
      if (e.key === 'Escape') {
        setIsUserDropdownOpen(false);
        setIsProjectDropdownOpen(false);
        setIsSearchFocused(false);
      }
    };

    document.addEventListener('mousedown', handleClickOutside);
    document.addEventListener('keydown', handleKeyDown);
    return () => {
      document.removeEventListener('mousedown', handleClickOutside);
      document.removeEventListener('keydown', handleKeyDown);
    };
  }, []);

  // Compute single-letter uppercase avatar initial (proper Turkish character support, e.g. Ümit -> Ü)
  const userInitial = currentUser?.name?.trim()
    ? currentUser.name.trim().charAt(0).toLocaleUpperCase('tr-TR')
    : 'U';

  const getRoleBadge = (r: string) => {
    switch (r) {
      case 'ADMIN':
        return { label: 'ADMIN', bg: 'bg-[var(--accent-primary)]/15 text-[var(--accent-primary)] border-[var(--accent-primary)]/30' };
      case 'TEST_LEAD':
        return { label: 'LEAD', bg: 'bg-indigo-500/15 text-indigo-600 dark:text-indigo-400 border-indigo-500/30' };
      case 'TESTER':
        return { label: 'TESTER', bg: 'bg-emerald-500/15 text-emerald-600 dark:text-emerald-400 border-emerald-500/30' };
      case 'AUTOMATION_ENGINEER':
        return { label: 'OTOMASYON', bg: 'bg-purple-500/15 text-purple-600 dark:text-purple-400 border-purple-500/30' };
      case 'VIEWER':
        return { label: 'VIEWER', bg: 'bg-slate-500/15 text-slate-600 dark:text-slate-400 border-slate-500/30' };
      default:
        return { label: r, bg: 'bg-slate-500/15 text-slate-400 border-slate-500/30' };
    }
  };

  const roleBadge = getRoleBadge(role);

  // Filter projects for selector
  const filteredProjects = projects.filter(
    (p) =>
      p.name.toLowerCase().includes(projectSearchQuery.toLowerCase()) ||
      p.key.toLowerCase().includes(projectSearchQuery.toLowerCase())
  );

  // Global search filtering results
  const searchResults = useMemo(() => {
    const q = globalSearchQuery.trim().toLowerCase();
    if (!q) return null;

    const matchedCases = (testCases || []).filter(
      (c) =>
        c.title?.toLowerCase().includes(q) ||
        c.code?.toLowerCase().includes(q) ||
        (c.description && c.description.toLowerCase().includes(q))
    ).slice(0, 5);

    const matchedPlans = (testPlans || []).filter(
      (p) =>
        p.title?.toLowerCase().includes(q) ||
        p.version?.toLowerCase().includes(q) ||
        (p.scope && p.scope.toLowerCase().includes(q))
    ).slice(0, 4);

    const matchedRuns = (testRuns || []).filter(
      (r) =>
        r.title?.toLowerCase().includes(q) ||
        r.version?.toLowerCase().includes(q) ||
        r.environment?.toLowerCase().includes(q) ||
        (r.executedBy && r.executedBy.toLowerCase().includes(q))
    ).slice(0, 4);

    const matchedDefects = (defects || []).filter(
      (d) =>
        d.key?.toLowerCase().includes(q) ||
        d.title?.toLowerCase().includes(q) ||
        (d.description && d.description.toLowerCase().includes(q)) ||
        (d.jiraBugKey && d.jiraBugKey.toLowerCase().includes(q)) ||
        (d.assignedTo && d.assignedTo.toLowerCase().includes(q)) ||
        (d.environment && d.environment.toLowerCase().includes(q))
    ).slice(0, 4);

    const matchedProj = (projects || []).filter(
      (p) => p.name?.toLowerCase().includes(q) || p.key?.toLowerCase().includes(q)
    ).slice(0, 3);

    return {
      cases: matchedCases,
      plans: matchedPlans,
      runs: matchedRuns,
      defects: matchedDefects,
      projects: matchedProj,
      total:
        matchedCases.length +
        matchedPlans.length +
        matchedRuns.length +
        matchedDefects.length +
        matchedProj.length,
    };
  }, [globalSearchQuery, testCases, testPlans, testRuns, defects, projects]);

  // Current active leaf item for breadcrumbs
  const getActiveLeaf = () => {
    if (activeTab === 'PLANS') {
      return selectedPlan ? selectedPlan.title : 'Test Planları';
    }
    if (activeTab === 'EXPLORER') {
      if (selectedCase) return `${selectedCase.code} - ${selectedCase.title}`;
      if (selectedSuite) return selectedSuite.name;
      return 'Test Senaryoları';
    }
    if (activeTab === 'RUNS') {
      return selectedRun ? selectedRun.title : 'Test Koşumları';
    }
    if (activeTab === 'DEFECTS') {
      return 'Defectler & Hatalar';
    }
    if (activeTab === 'REPORTS') {
      return 'Test Raporları';
    }
    return null;
  };

  const activeLeaf = getActiveLeaf();

