                                {r.title}
                              </p>
                              <div className="flex items-center gap-2 mt-0.5 text-[10px] text-slate-400 font-mono">
                                <span>{r.version}</span>
                                {r.environment && <span>• {r.environment}</span>}
                                {r.executedBy && <span>• {r.executedBy}</span>}
                              </div>
