                {can('CREATE_PROJECT') && onOpenNewProject && (
                  <div className="p-2 border-t border-slate-100 dark:border-slate-800 bg-slate-50/70 dark:bg-slate-900/60">
                    <button
                      type="button"
                      onClick={() => {
                        setIsProjectDropdownOpen(false);
