                            : stStatus === 'FAILED'
                            ? 'bg-red-500/5 dark:bg-red-500/10 border-red-500/30'
                            : stStatus === 'BLOCKED'
                            ? 'bg-amber-500/5 dark:bg-amber-500/10 border-amber-500/30'
